  // ── Client CRUD ───────────────────────────────────────────────────────────────
  async function createClient() {
    if (!nc.first_name.trim()) { showToast('First name required.'); return; }
    if (nc.lease_expiration_date && !nc.lxp_follow_up_days) { showToast('Please select a contact window (90/120/180/360d) for the LXP date.'); return; }
    setSaving(true);
    // Duplicate email check — only when an email is provided
    if (nc.email.trim()) {
      const { data: existing } = await supabase
        .from('crm_clients')
        .select('id, first_name, last_name')
        .eq('business_unit', businessUnit)
        .ilike('email', nc.email.trim())
        .maybeSingle();
      if (existing) {
        showToast(`A contact with that email already exists: ${existing.first_name} ${existing.last_name}`);
        setSaving(false);
        return;
      }
    }
    const { data: createdRow, error } = await supabase.from('crm_clients').insert([{
      ...nc,
      agent_id: profile!.id,
      business_unit: businessUnit,
      // Contacts @-tagged in the notes — who else was in the meeting.
      tagged_contact_ids: parseMentionContactIds(nc.notes, clients, profiles),
      // date columns reject empty strings — coerce to null
      lease_expiration_date: nc.lease_expiration_date || null,
      birthday: nc.birthday || null,
    }]).select('id').single();
    if (error) { showToast('Error: ' + error.message); } else {
      showToast(`${nc.first_name} ${nc.last_name} added`);
      // Read from the saved note (not from keystroke state, which a cancelled form leaves behind), linked to the new card.
      const mentioned = parseMentionIds(nc.notes, profiles);
      if (mentioned.length) await createMentionNotifications(mentioned, `@${profile?.first_name} mentioned you in notes for ${nc.first_name} ${nc.last_name}`, 'contact', createdRow?.id);
      setMentionedIds([]);
      setNc({ first_name: '', last_name: '', business_name: '', email: '', phone: '', cell_phone: '', address: '', city: '', state: '', zip: '', brokerage: '', license: '', budget: '', size_range: '', asset_types: [], type: 'Buyer', tags: [], lead_source: '', notes: '', lease_expiration_date: '', lxp_follow_up_days: null, birthday: '' });
      setShowAddClient(false);
      loadClients(profile!, 0, true);
    }
    setSaving(false);
  }

  /**
   * Explain a refused contact delete instead of leaving an opaque failure.
   *
   * crm_deals.client_id is ON DELETE RESTRICT: a deal is financial history and
   * must never silently detach from its contact — that is exactly how the Dita
   * Lawson deal ended up orphaned. Postgres answers 23503, which on its own
   * tells the person nothing about what to do next.
   */
  function contactDeleteMessage(error: { code?: string; message?: string } | null, subject: string): string {
    const code = error?.code ?? '';
    const msg = error?.message ?? '';
    if (code === '23503' || /foreign key|violates/i.test(msg)) {
      if (/crm_deals/i.test(msg)) {
        return `${subject} has deals attached — reassign or delete those deals first, then remove the contact.`;
      }
      return `${subject} still has linked records — remove or reassign them first.`;
    }
    return `Could not remove ${subject}. Nothing was deleted.`;
  }

  async function deleteClient(id: string, name: string) {
    if (!isSuperAdmin) { showToast('Only a super admin can delete contacts.'); return; }
    if (!confirm(`Remove ${name}? This cannot be undone.`)) return;
    const { error } = await supabase.from('crm_clients').delete().eq('id', id);
    // Without this the row vanished from the list and the toast said "removed"
    // even when the delete was refused — a false success that reverted on the
    // next reload.
    if (error) { showToast(contactDeleteMessage(error, name)); return; }
    setClients(prev => prev.filter(c => c.id !== id));
    showToast(`${name} removed.`);
  }

  async function massDeleteClients() {
    if (!isSuperAdmin) { showToast('Only a super admin can delete contacts.'); return; }
    const count = selectedClientIds.size;
    if (count === 0) return;
    if (!confirm(`Permanently delete ${count} contact${count !== 1 ? 's' : ''}? This cannot be undone.`)) return;
    const ids = [...selectedClientIds];
    const { error } = await supabase.from('crm_clients').delete().in('id', ids);
    // One statement, so a single protected contact refuses the whole batch and
    // NOTHING is deleted. Say that plainly rather than clearing the selection
    // and claiming success.
    if (error) {
      showToast(
        (error as { code?: string }).code === '23503'
          ? 'None were deleted — at least one of those contacts has deals attached. Reassign or delete those deals first.'
          : 'None were deleted. Nothing was changed.',
      );
      return;
    }
    setClients(prev => prev.filter(c => !ids.includes(c.id)));
    setSelectedClientIds(new Set());
    showToast(`${count} contact${count !== 1 ? 's' : ''} deleted.`);
  }

  // Scan the loaded contacts for duplicates (same email, or same first+last name) and open
  // the merge review. Works off `clients` (which holds every contact), so it's accurate.
  function openMergeDuplicates() {
    // Don't scan a half-loaded list — that would wrongly report "no duplicates."
    if (clients.length === 0 || (contactsTotal > 0 && clients.length < contactsTotal)) {
      showToast(`Contacts are still loading (${clients.length}${contactsTotal ? ` of ${contactsTotal}` : ''}) — give it a moment and try again.`);
      return;
    }
    const emailNorm = (e: unknown) => String(e ?? '').toLowerCase().trim().replace(/,+$/, '');
    const emailsOf = (c: Client) => [c.email, ...(c.extra_emails ?? [])].map(emailNorm).filter(e => e && e.includes('@'));
    const nameKey = (c: Client) => {
      const fn = (c.first_name ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
      const ln = (c.last_name ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
      return fn && ln && (fn + ln).length > 4 ? `${fn}|${ln}` : '';
    };
    const score = (c: Client) => (emailsOf(c).length ? 100 : 0)
      + ['phone', 'cell_phone', 'business_name', 'address', 'notes'].filter(f => String((c as unknown as Record<string, unknown>)[f] ?? '').trim()).length
      + (c.tags?.length ?? 0) * 0.1 + (c.last_touched_at ? 5 : 0);
    const byEmail: Record<string, Client[]> = {};
    const byName: Record<string, Client[]> = {};
    for (const c of clients) {
      for (const e of emailsOf(c)) (byEmail[e] ??= []).push(c);
      const k = nameKey(c);
      if (k) (byName[k] ??= []).push(c);
    }
    const out: typeof mergeClusters = [];
    const seen = new Set<string>();
    const add = (members: Client[], kind: 'email' | 'name') => {
      const ids = [...new Set(members.map(m => m.id))];
      if (ids.length < 2) return;
      const key = ids.slice().sort().join(',');
      if (seen.has(key)) return;
      seen.add(key);
      const uniqueMembers = ids.map(id => members.find(m => m.id === id)!);
      const nm = `${uniqueMembers[0].first_name} ${uniqueMembers[0].last_name}`;
      if (/^\s*(not available|unknown|n\/a)\s*$/i.test(nm.trim())) return;
      const survivor = [...uniqueMembers].sort((a, b) => score(b) - score(a))[0];
      out.push({ key, kind, members: uniqueMembers, survivorId: survivor.id });
    };
    for (const arr of Object.values(byEmail)) add(arr, 'email');
    for (const arr of Object.values(byName)) add(arr, 'name');
    out.sort((a, b) => (a.kind === b.kind ? 0 : a.kind === 'email' ? -1 : 1));
    setMergeClusters(out);
    setShowMergeModal(true);
  }

  async function mergeCluster(cluster: (typeof mergeClusters)[number]) {
    const dupIds = cluster.members.map(m => m.id).filter(id => id !== cluster.survivorId);
    if (dupIds.length === 0) return;
    setMergeBusy(cluster.key);
    try {
      const res = await fetch('/api/crm/merge-contacts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...(session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {}) },
        body: JSON.stringify({ primaryId: cluster.survivorId, dupIds }),
      });
      const j = await res.json().catch(() => ({}));
      if (!res.ok) { showToast(j.error ?? 'Merge failed'); setMergeBusy(null); return; }
      const keptName = `${cluster.members.find(m => m.id === cluster.survivorId)?.first_name ?? ''} ${cluster.members.find(m => m.id === cluster.survivorId)?.last_name ?? ''}`.trim();
      setClients(prev => prev
        .filter(c => !dupIds.includes(c.id))
        .map(c => (c.id === cluster.survivorId && j.primary ? { ...c, ...j.primary } : c)));
      setContactsTotal(t => Math.max(0, t - dupIds.length));
      setMergeClusters(prev => prev.filter(cl => cl.key !== cluster.key));
      showToast(`Merged ${dupIds.length + 1} records into ${keptName || 'the survivor'} ✓`);
    } catch {
      showToast('Network error during merge');
    }
    setMergeBusy(null);
  }

