  /**
   * Snap a typed tag to the spelling already in the book.
   *
   * The autocomplete suggests existing tags, but nothing stopped someone typing
   * past it: the de-dupe was case-sensitive, so "property owner" was accepted
   * alongside "Property Owner" as a second tag. Campaign and action-plan
   * audiences then matched only one of them. Reusing the established casing
   * means the vocabulary stops fragmenting at the point of entry rather than
   * being cleaned up afterwards.
   */
  function canonicalTag(raw: string): string {
    const t = raw.trim().replace(/,$/, '').trim();
    if (!t) return t;
    const existing = [...clients.flatMap(c => c.tags ?? []), ...deals.flatMap(d => d.tags ?? [])];
    return existing.find(e => e.toLowerCase() === t.toLowerCase()) ?? t;
  }

  async function bulkTagContacts(mode: 'add' | 'remove') {
    // Tag as typed. This used to force .toLowerCase() while single-contact
    // tagging kept the case, so bulk-tagging "Property Owner" quietly created a
    // SECOND tag "property owner" — and the campaign and action-plan audience
    // filters match exactly, so those contacts then fell out of the very
    // campaigns they had just been tagged for. Matching below is
    // case-insensitive so the variants already in the book still line up.
    const tag = canonicalTag(bulkTagValue);
    if (!tag || selectedClientIds.size === 0) return;
    const toUpdate = clients.filter(c => selectedClientIds.has(c.id));
    const nextTags = (current: string[]) => mode === 'add'
      ? (current.some(t => t.toLowerCase() === tag.toLowerCase()) ? current : [...current, tag])
      : current.filter(t => t.toLowerCase() !== tag.toLowerCase());

    // One round trip per contact; fine for a hand-made selection, and it keeps
    // each row's own tag list intact rather than overwriting with a shared array.
    for (const c of toUpdate) {
      await supabase.from('crm_clients').update({ tags: nextTags(c.tags ?? []) }).eq('id', c.id);
    }
    setClients(prev => prev.map(c =>
      selectedClientIds.has(c.id) ? { ...c, tags: nextTags(c.tags ?? []) } : c));
    showToast(`Tag "${tag}" ${mode === 'add' ? 'added to' : 'removed from'} ${toUpdate.length} contact${toUpdate.length !== 1 ? 's' : ''}`);
    setShowBulkTag(false);
    setBulkTagValue('');
  }

  // ── Task Management ───────────────────────────────────────────────────────────
  // Accepts an optional profile so the initial-load callers can pass the freshly loaded
  // one: they fire from a setTimeout that closes over `profile` while it is still null.
  async function loadAllTasks(p?: Profile) {
    const agent = p ?? profile;
    if (!agent) return;
    const { data } = await supabase
      .from('crm_tasks')
      .select('*')
      .eq('agent_id', agent.id)
      .is('completed_at', null)
      .order('due_date', { ascending: true });
    setAllTasks((data ?? []) as CRMTask[]);
  }

  // Load another agent's open call/follow-up tasks (admin agent-switcher on the Call Queue).
  async function loadCallView(agentId: string) {
    if (!agentId) { setCallViewTasks([]); return; }
    const { data } = await supabase
      .from('crm_tasks')
      .select('*')
      .eq('agent_id', agentId)
      .is('completed_at', null)
      .order('due_date', { ascending: true });
    setCallViewTasks((data ?? []) as CRMTask[]);
  }

  // Load the Tasks page's data whenever it becomes active by ANY path — a nav click,
  // the initial #tasks page load, or browser back/forward. Previously only the nav
  // buttons' onClick loaded it, so arriving any other way showed an empty tab until
  // you clicked out and back in.
  useEffect(() => {
    if (page === 'tasks' && session) {
      loadTasks(); loadAllTasks(); loadProfiles(); loadClients();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page, session, businessUnit]);

  async function saveTask() {
    if (!taskClientId || !taskForm.due_date || !taskForm.title.trim()) return;
    const { data, error } = await supabase.from('crm_tasks').insert([{
      client_id: taskClientId,
      agent_id: profile!.id,
      type: taskForm.type,
      title: taskForm.title.trim(),
      due_date: taskForm.due_date,
      notes: taskForm.notes.trim(),
    }]).select().single();
    if (error) { showToast('Error saving task'); return; }
    {
      const who = parseMentionIds(`${taskForm.title} ${taskForm.notes}`, profiles);
      if (who.length) {
        const n = taskForm.notes.trim();
        createMentionNotifications(who, `@${profile?.first_name} tagged you on a ${taskForm.type === 'call' ? 'call task' : 'task'}: ${taskForm.title.trim()}${n ? ` — ${n.length > 80 ? n.slice(0, 80) + '…' : n}` : ''}`, 'task', (data as CRMTask).id);
      }
    }
    setAllTasks(prev => [...prev, data as CRMTask].sort((a, b) => a.due_date.localeCompare(b.due_date)));
    setShowTaskModal(false);
    setTaskForm({ type: 'follow_up', title: '', due_date: '', notes: '' });

    // Push to Google Calendar (fire-and-forget — task is already saved regardless)
    const client = clients.find(c => c.id === taskClientId);
    fetch('/api/calendar/create', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        userId: profile!.id,
        title: taskForm.title.trim(),
        due_date: taskForm.due_date,
        notes: taskForm.notes.trim(),
        client_name: client ? `${client.first_name} ${client.last_name}` : '',
        task_type: taskForm.type,
      }),
    }).then(r => r.json()).then(res => {
      if (res.error === 'scope_missing') {
        showToast('Task saved — reconnect Google in Settings to enable calendar sync');
      } else if (res.success) {
        showToast('Task saved + added to Google Calendar ✓');
      } else {
        showToast('Task saved (calendar sync unavailable)');
      }
    }).catch(() => showToast('Task saved'));
  }

  async function completeTask(taskId: string) {
    const task = allTasks.find(t => t.id === taskId);
    const now = new Date().toISOString();
    await supabase.from('crm_tasks').update({ completed_at: now }).eq('id', taskId);
    setAllTasks(prev => prev.filter(t => t.id !== taskId));
    showToast('Task completed ✓');
    // Log a touch on the linked contact
    if (task?.client_id) {
      logActivity(task.client_id, 'note', `✅ Task completed: ${task.title}`);
      if (activeClient?.id === task.client_id) loadClientTasks(task.client_id);
    }
  }

  async function loadClientTasks(clientId: string) {
    const headers: Record<string,string> = session?.access_token ? { 'Authorization': `Bearer ${session.access_token}` } : {};
    const res = await fetch(`/api/crm/tasks?unit=${businessUnit}&status=all&client_id=${clientId}`, { headers });
    if (!res.ok) return;
    const json = await res.json();
    setClientCardTasks((json.tasks ?? []) as Task[]);
  }

  // ── Today's Calls: disposition + auto next-follow-up ──────────────────────────
  // Assign the people in the current list view (or just the ticked ones) to an agent as open call tasks.
  async function assignCallList(queueItems: CRMTask[], sourceLabel: string) {
    if (callAssigning) return;
    const chosen = callPicked.size ? queueItems.filter(t => callPicked.has(t.client_id)) : queueItems;
    let remembered = '';
    try { remembered = localStorage.getItem('crm:callAssignTo') ?? ''; } catch { /* storage blocked */ }
    const to = callAssignTo || (profiles.some(p => p.id === remembered) ? remembered : '')
      || profiles.find(p => p.id !== profile?.id && /^brian$/i.test(p.first_name ?? ''))?.id || profiles.find(p => p.id !== profile?.id)?.id || '';
    if (!to || chosen.length === 0) return;
    setCallAssigning(true);
    try {
      const d = new Date();
      if (callAssignDue === 'tomorrow') d.setDate(d.getDate() + 1); else if (callAssignDue === '3d') d.setDate(d.getDate() + 3);
      const due = d.toLocaleDateString('en-CA');
      const items = chosen.map(t => {
        const m = callListMeta.get(t.id);
        const who = m?.business || m?.contactName || nameOfClient(t.client_id) || 'contact';
        return {
          client_id: t.client_id,
          title: `Call ${who}${m ? ` — ${m.reason}` : ''}`.slice(0, 240),
          // First line = the exact campaign (what the Call Queue groups by); then where the list came from, who to ask for, engagement.
          description: [`From: ${m?.primaryCampaign || sourceLabel}`, m?.primaryCampaign && m.primaryCampaign !== sourceLabel ? `List: ${sourceLabel}` : '', m?.askFor ? `📞 ${m.askFor}` : '',
            m ? `${m.emailsSent} emailed · ${m.emailsOpened} opened${m.clicks ? ` · ${m.clicks} clicks` : ''}` : '', m && m.campaignNames.length > 1 ? `Emailed in: ${m.campaignNames.join(' · ')}` : ''].filter(Boolean).join('\n'),
          priority: m?.heat === 'hot' ? 'high' : 'normal',
        };
      });
      const res = await fetch('/api/crm/tasks/assign-calls', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...(session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {}) },
        body: JSON.stringify({ assigned_to: to, due_date: due, business_unit: businessUnit, items, set_owner: callListMode === 'leads:web' }),
      });
      const j = await res.json().catch(() => ({}));
      if (!res.ok) { showToast(j.error ?? 'Could not assign the calls'); return; }
      const first = (j.assignee_name as string | undefined)?.split(' ')[0] ?? 'agent';
      showToast(`Assigned ${j.created} call${j.created === 1 ? '' : 's'} to ${first}${j.skipped_existing ? ` (${j.skipped_existing} already in their queue)` : ''} ✓`);
      setCallAssignedTo(prev => { const n = new Map(prev); for (const t of chosen) n.set(t.client_id, first); return n; });
      setCallPicked(new Set());
      setCallAssignNonce(n => n + 1);
    } finally { setCallAssigning(false); }
  }

  // The number the agent dials for a queue item: the contact's phone, else the prospect's, else the call-back's.
  function callPhoneFor(task: CRMTask): string {
    const cl = clients.find(x => x.id === task.client_id);
    const own = cl ? (cl.phone || cl.cell_phone || '') : '';
    if (own) return own;
    const pm = callListMeta.get(task.id)?.phone;
    if (pm) return pm;
    const cb = callbackMeta.get(task.id);
    return cb ? (cb.callback_number || cb.from_number || cb.to_number || '') : '';
  }
  function nameOfClient(id: string): string | null {
    const cl = clients.find(x => x.id === id);
    if (!cl) return null;
    return `${cl.first_name ?? ''} ${cl.last_name ?? ''}`.trim() || cl.business_name || null;
  }

  function saveCallGoal(v: number) {
    const g = Math.round(v);
    setCallGoal(g);
    try { localStorage.setItem('crm:callGoal', String(g)); } catch { /* ignore */ }
    if (!profile?.id) return;
    supabase.from('crm_profiles').update({ daily_call_goal: g }).eq('id', profile.id).then(({ error }) => {
      if (error) showToast('Goal saved on this device only — ask your admin to run the daily-goal migration to sync it');
      else setProfile(p => (p ? { ...p, daily_call_goal: g } : p));
    });
  }
  async function dispositionCall(task: CRMTask, disposition: 'connected' | 'voicemail' | 'no_answer' | 'wrong_number' | 'not_interested' | 'call_back') {
    if (callActionInFlight) return;
    setCallActionInFlight(true);
    try {
      // 1) Complete the current call task (sets completed_at + status='done'). A person pulled from a
      //    marketing list has no task yet — they just leave this session's list; the call logged below
      //    is what marks them contacted everywhere else.
      const cb = callbackMeta.get(task.id) ?? null;
      const startedAt = new Date().toISOString();           // undo deletes only what this tap wrote
      // Who comes after this one — captured BEFORE the queue changes, so auto-advance never skips or repeats.
      const qi = callQueue.findIndex(t => t.id === task.id);
      const upNext = qi >= 0 ? (callQueue[qi + 1] ?? null) : null;
      const undo: { taskId?: string; cbId?: string; cbPrevDue?: string | null; callLogId?: string; prospectClientId?: string; nextTaskId?: string; dncPrevTags?: string[] } = {};
      if (cb) undo.cbPrevDue = cb.follow_up_due ?? null;
      if (task.id.startsWith('p:')) undo.prospectClientId = task.client_id;
      else if (cb) undo.cbId = cb.id;
      else undo.taskId = task.id;
      if (task.id.startsWith('p:')) setCallProspectDoneIds(prev => new Set(prev).add(task.client_id));
      else if (cb) { /* a call-back lives in the Calling Log — resolved below, not a task */ }
      else await completeTask(task.id);

      // 2) Log the call activity on the client's timeline (fold in the agent's note)
      const dispLabel = disposition === 'not_interested' ? 'Not interested' : disposition === 'call_back' ? 'Connected — call back requested' : disposition === 'connected' ? 'Connected' : disposition === 'voicemail' ? 'Left voicemail' : disposition === 'wrong_number' ? 'Wrong number' : 'No answer';
      const jotted = callNote.trim();
      callNoteSavedRef.current = task.id;   // this call's note is being saved with its outcome — don't flush it again
      let base = task.title ? `Call — ${dispLabel} — ${task.title}` : `Call — ${dispLabel}`;
      // Speed-to-lead: the first call on a new website lead records how fast we got to them (business minutes).
      if (task.id.startsWith('p:') && task.created_at && !leadFirstCall[task.client_id] && newLeadContacts.some(l => l.id === task.client_id)) {
        base += ` — ⚡ First contact ${fmtMins(businessMinutesBetween(task.created_at))} after the lead came in`;
      }
      // Property-based prospecting calls have no linked contact — skip the timeline log.
      if (task.client_id) await logActivity(task.client_id, 'call', jotted ? `${base} — ${jotted}` : base);
      else if (jotted) {
        // No contact to log on, so logActivity (which notifies) never runs — ping tagged teammates here.
        const who = parseMentionIds(jotted, profiles);
        if (who.length) createMentionNotifications(who, `@${profile?.first_name} tagged you on a call (${(task.title || 'call').replace(/^🏢\s*/, '').slice(0, 60)}): ${jotted.length > 90 ? jotted.slice(0, 90) + '…' : jotted}`, 'task', task.id.startsWith('p:') || task.id.startsWith('cb:') ? undefined : task.id);
      }

      // 2b) Not interested = do not call: tag the contact so the queue, call lists and call-backs skip them.
      if (disposition === 'not_interested' && task.client_id) {
        const cl = clients.find(x => x.id === task.client_id);
        if (cl && !isDnc(cl)) {
          const nextTags = [...(cl.tags ?? []), DNC_TAG];
          const { error: tagErr } = await supabase.from('crm_clients').update({ tags: nextTags }).eq('id', cl.id);
          if (!tagErr) {
            undo.dncPrevTags = cl.tags ?? [];
            setClients(prev => prev.map(x => x.id === cl.id ? { ...x, tags: nextTags } : x));
            setActiveClient(prev => prev && prev.id === cl.id ? { ...prev, tags: nextTags } : prev);
          } else showToast('Logged, but could not mark Do Not Call');
        }
      }

      // 3) Auto-create the next follow-up task unless the agent chose "No follow-up".
      //    A chip override (callFollowUpDays) beats the disposition's default cadence.
      // A wrong number needs no callback — the note on the timeline is the follow-up (fix the number on the contact).
      // Not interested closes the loop — no follow-up unless the agent explicitly picked a chip.
      if (callFollowUpDays !== 'none' && disposition !== 'wrong_number' && !(disposition === 'not_interested' && callFollowUpDays === null) && !cb) {
        const defaultDays = disposition === 'no_answer' ? 1 : disposition === 'voicemail' ? 2 : disposition === 'call_back' ? 1 : 7;
        const addDays = typeof callFollowUpDays === 'number' ? callFollowUpDays : defaultDays;
        const nextType: 'call' | 'follow_up' = disposition === 'connected' || disposition === 'not_interested' ? 'follow_up' : 'call';
        const baseTitle = disposition === 'no_answer' ? 'Call back — no answer' : disposition === 'voicemail' ? 'Follow up — left voicemail' : 'Follow up';
        // Carry the property/subject into the follow-up when there's no contact to anchor it.
        const nextTitle = task.client_id ? baseTitle : `${baseTitle} — ${(task.title || '').replace(/^🏢\s*/, '').slice(0, 90)}`;
        const d = new Date(); d.setDate(d.getDate() + addDays);
        const nextDue = d.toISOString().slice(0, 10);
        const { data: nt } = await supabase.from('crm_tasks').insert([{
          client_id: task.client_id,
          // Keep the follow-up in the SAME agent's queue (an admin may be working someone else's calls).
          agent_id: task.agent_id ?? profile!.id,
          type: nextType,
          title: nextTitle,
          due_date: nextDue,
          notes: jotted || (task.notes ?? ''),
          business_unit: businessUnit,
          status: 'open',
        }]).select('id').single();
        if (nt?.id) undo.nextTaskId = nt.id as string;
      }

      // 3b) The Calling Log gets the call too (it used to hold only calls the phone system saw). For a
      //     call-back this also resolves it: talking to them or a wrong number closes it; a voicemail / no
      //     answer keeps it open and moves its due time (the follow-up chip, else 1 day / 2 days).
      const digits = (task.id.startsWith('cb:') && cb ? (cb.callback_number || cb.from_number || cb.to_number || '') : (callPhoneFor(task) || '')).replace(/\D/g, '').slice(-10);
      if (digits.length === 10) {
        const result = disposition === 'connected' || disposition === 'not_interested' || disposition === 'call_back' ? 'answered' : disposition === 'voicemail' ? 'left_voicemail' : disposition === 'wrong_number' ? 'wrong_number' : 'no_answer';
        let retryAt: string | null = null;
        if (cb && (result === 'left_voicemail' || result === 'no_answer') && callFollowUpDays !== 'none') {
          const days = typeof callFollowUpDays === 'number' ? callFollowUpDays : result === 'no_answer' ? 1 : 2;
          const d = new Date(); d.setDate(d.getDate() + days); d.setHours(9, 0, 0, 0); retryAt = d.toISOString();
        }
        const dialedAt = callDialed && callDialed.taskId === task.id ? callDialed.at : null;
        try {
          const postRes = await fetch('/api/crm/calls', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...(session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {}) },
            body: JSON.stringify({
              business_unit: businessUnit, direction: 'outbound', number: digits,
              caller_name: cb ? (cb.contact?.name || cb.caller_name || null) : (clients.find(x => x.id === task.client_id) ? nameOfClient(task.client_id) : null),
              contact_id: task.client_id || cb?.contact_id || null, result,
              duration_sec: result === 'answered' && dialedAt ? Math.min(Math.round((Date.now() - dialedAt) / 1000), 3600) : null,
              notes: jotted || null, started_at: dialedAt ? new Date(dialedAt).toISOString() : undefined,
              resolves_call_id: cb ? cb.id : undefined, retry_at: retryAt,
            }),
          });
          const pj = await postRes.json().catch(() => null);
          if (pj?.call?.id) undo.callLogId = pj.call.id as string;
        } catch { /* the activity above is saved; the log entry can be added from the Calling Log */ }
      }
      if (cb) { setCallbackDoneIds(prev => new Set(prev).add(cb.id)); loadCallbacks(); }
      window.dispatchEvent(new Event('crm:calls-changed'));   // the Calling Log refreshes itself

      // 4) Reset the per-call inputs, bump the counter, refresh the queue in view, and advance
      setCallNote(''); setCallFollowUpDays(null);
      setCallsDoneThisSession(n => n + 1);
      // Phone: land on the next call at the top, with a small buzz so you know it saved.
      setCallDialed(null); setCallReturnOpen(false);
      try { navigator.vibrate?.(25); } catch { /* not supported */ }
      try { document.querySelector('.crm-page-scroll')?.scrollTo({ top: 0, behavior: 'smooth' }); } catch { /* ignore */ }
      if (callViewAgentId) await loadCallView(callViewAgentId); else await loadAllTasks();

      // Auto-advance: land on the call that followed this one, and say so — with Undo for any outcome.
      const labelOf = (t: CRMTask) => callListMeta.get(t.id)?.business || callListMeta.get(t.id)?.contactName || callbackMeta.get(t.id)?.contact?.name || callbackMeta.get(t.id)?.caller_name || nameOfClient(t.client_id) || (t.title || 'next call').replace(/^🏢\s*/, '');
      if (upNext && !callSkippedIds.has(upNext.id)) setCallSelectedId(upNext.id); else setCallSelectedId(null);
      {
        const who = nameOfClient(task.client_id) || labelOf(task);
        setCallUndo({
          label: `✓ ${dispLabel}${undo.dncPrevTags ? ' · marked Do Not Call' : ''}`,
          next: upNext ? labelOf(upNext) : undefined,
          run: async () => {
            const cid = task.client_id;
            const hdr = { 'Content-Type': 'application/json', ...(session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {}) };
            if (undo.nextTaskId) await supabase.from('crm_tasks').delete().eq('id', undo.nextTaskId);
            if (undo.taskId) await supabase.from('crm_tasks').update({ completed_at: null }).eq('id', undo.taskId);
            if (undo.cbId) {
              try {
                await fetch(`/api/crm/calls?id=${undo.cbId}`, { method: 'PATCH', headers: hdr, body: JSON.stringify({ handled: false, needs_follow_up: true, follow_up_due: undo.cbPrevDue ?? null }) });
              } catch { /* it will show up in the Calling Log */ }
              setCallbackDoneIds(prev => { const n = new Set(prev); n.delete(undo.cbId!); return n; });
              loadCallbacks();
            }
            // The Calling Log row can't be deleted by an agent — mark it so it isn't read as a real attempt.
            if (undo.callLogId) { try { await fetch(`/api/crm/calls?id=${undo.callLogId}`, { method: 'PATCH', headers: hdr, body: JSON.stringify({ notes: '↩ Outcome undone by agent', needs_follow_up: false }) }); } catch { /* best effort */ } }
            if (undo.prospectClientId) setCallProspectDoneIds(prev => { const n = new Set(prev); n.delete(undo.prospectClientId!); return n; });
            if (undo.dncPrevTags && cid) {
              await supabase.from('crm_clients').update({ tags: undo.dncPrevTags }).eq('id', cid);
              setClients(prev => prev.map(x => x.id === cid ? { ...x, tags: undo.dncPrevTags! } : x));
              setActiveClient(prev => prev && prev.id === cid ? { ...prev, tags: undo.dncPrevTags! } : prev);
            }
            // Take back the timeline entries this tap wrote (the call + "task completed" + any follow-up note).
            if (cid && profile?.id) await supabase.from('crm_client_activities').delete().eq('client_id', cid).eq('agent_id', profile.id).gte('created_at', new Date(Date.parse(startedAt) - 5000).toISOString());
            setCallsDoneThisSession(n => Math.max(0, n - 1));
            setCallSkippedIds(prev => { const n = new Set(prev); n.delete(task.id); return n; });
            setCallSelectedId(task.id);
            if (callViewAgentId) await loadCallView(callViewAgentId); else await loadAllTasks();
            showToast(`Undone — ${who} is back on top`);
          },
        });
      }
    } finally {
      setCallActionInFlight(false);
    }
  }

  // Snooze: unlike Skip (this session only) this really moves the call to tomorrow.
  async function snoozeCall(task: CRMTask) {
    if (callActionInFlight) return;
    const d = new Date(); d.setDate(d.getDate() + 1);
    const tomorrow = d.toLocaleDateString('en-CA');
    const cb = callbackMeta.get(task.id) ?? null;
    const qi = callQueue.findIndex(t => t.id === task.id);
    const upNext = qi >= 0 ? (callQueue[qi + 1] ?? null) : null;
    const prevDue = task.due_date;
    const prevCbDue = cb?.follow_up_due ?? null;
    const hdr = { 'Content-Type': 'application/json', ...(session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {}) };
    if (task.id.startsWith('p:')) { skipCall(task.id); showToast('Skipped for now — it will be back next time you open the queue'); return; }
    if (cb) {
      const at = new Date(d); at.setHours(9, 0, 0, 0);
      const r = await fetch(`/api/crm/calls?id=${cb.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', ...(session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {}) }, body: JSON.stringify({ follow_up_due: at.toISOString() }) });
      if (!r.ok) { showToast('Could not snooze it'); return; }
      loadCallbacks();
    } else {
      const { error } = await supabase.from('crm_tasks').update({ due_date: tomorrow }).eq('id', task.id);
      if (error) { showToast('Could not snooze it'); return; }
      if (callViewAgentId) await loadCallView(callViewAgentId); else await loadAllTasks();
    }
    skipCall(task.id);
    if (upNext) setCallSelectedId(upNext.id);
    setCallUndo({
      label: '😴 Snoozed to tomorrow',
      next: upNext ? (callListMeta.get(upNext.id)?.business || callListMeta.get(upNext.id)?.contactName || callbackMeta.get(upNext.id)?.contact?.name || nameOfClient(upNext.client_id) || upNext.title) : undefined,
      run: async () => {
        if (cb) await fetch(`/api/crm/calls?id=${cb.id}`, { method: 'PATCH', headers: hdr, body: JSON.stringify({ follow_up_due: prevCbDue }) });
        else await supabase.from('crm_tasks').update({ due_date: prevDue }).eq('id', task.id);
        setCallSkippedIds(prev => { const n = new Set(prev); n.delete(task.id); return n; });
        setCallSelectedId(task.id);
        if (cb) loadCallbacks(); else if (callViewAgentId) await loadCallView(callViewAgentId); else await loadAllTasks();
        showToast('Snooze undone');
      },
    });
  }

  function skipCall(taskId: string) {
    setCallSkippedIds(prev => { const next = new Set(prev); next.add(taskId); return next; });
  }

  // ── Call Queue ── your own (allTasks) unless an admin is viewing another agent
  //    (callViewAgentId → callViewTasks). Lifted so keyboard shortcuts can act on it.
  const callSource = callViewAgentId ? callViewTasks : allTasks;
  // People-to-call lists become synthetic tasks (id 'p:<clientId>') so the workspace, keyboard shortcuts,
  // outcome logging and follow-up scheduling all work unchanged; dispositionCall skips the task update for them.
  // New leads — website forms, lead magnets, tour requests and inbound-call leads saved as contacts: anyone tagged "New Lead"
  // in the last 30 days, newest first. Same list machinery as the marketing lists, so they can be worked or assigned.
  const newLeadContacts = useMemo(() => {
    const cutoff = Date.now() - 30 * 86_400_000;
    return clients.filter(c => (c.tags ?? []).includes('New Lead') && !isDnc(c) && !(c.tags ?? []).some(t => /^recruiting/i.test(t)) && Date.parse(c.created_at) >= cutoff);
  }, [clients]);
  // Who has already had a call logged — new leads that have been called leave the "new" section.
  // client id → when their FIRST call was logged (ignoring anything before the lead existed). Drives speed-to-lead.
  const [leadFirstCall, setLeadFirstCall] = useState<Record<string, string>>({});
  const calledLeadIds = useMemo(() => new Set(Object.keys(leadFirstCall)), [leadFirstCall]);
  // Ticks every 30s on the call queue so "⚡ 4m since it came in" counts up on its own.
  const [stlNow, setStlNow] = useState(() => Date.now());
  useEffect(() => {
    if (page !== 'tasks' || tasksSubTab !== 'calls') return;
    const i = setInterval(() => setStlNow(Date.now()), 30_000);
    return () => clearInterval(i);
  }, [page, tasksSubTab]);
  useEffect(() => {
    if (page !== 'tasks' || tasksSubTab !== 'calls') return;
    const ids = newLeadContacts.map(c => c.id);
    if (!ids.length) return;
    let cancelled = false;
    (async () => {
      const got: Record<string, string> = {};
      for (let i = 0; i < ids.length; i += 100) {
        const { data } = await supabase.from('crm_client_activities').select('client_id, created_at').eq('type', 'call').in('client_id', ids.slice(i, i + 100)).order('created_at', { ascending: true });
        for (const a of (data ?? []) as { client_id: string; created_at: string }[]) {
          // Earliest call wins (ascending order). Any call counts as "contacted", as before.
          if (!(a.client_id in got)) got[a.client_id] = a.created_at;
        }
      }
      if (!cancelled) setLeadFirstCall(got);
    })();
    return () => { cancelled = true; };
  }, [page, tasksSubTab, newLeadContacts, callsDoneThisSession]);
  // Speed-to-lead scoreboard (all agents): how fast the last 7 days of new leads got their first call, and who's still waiting.
  const leadResponse = useMemo(() => {
    const weekAgo = stlNow - 7 * 86_400_000;
    const resp: number[] = []; const waiting: number[] = [];
    for (const c of newLeadContacts) {
      const made = Date.parse(c.created_at); const fc = leadFirstCall[c.id];
      if (fc) { const f = Date.parse(fc); if (made >= weekAgo && f >= made) resp.push(businessMinutesBetween(c.created_at, f)); }
      else if (c.cell_phone || c.phone) waiting.push(businessMinutesBetween(c.created_at, stlNow));
    }
    resp.sort((a, b) => a - b);
    const median = resp.length ? resp[Math.floor(resp.length / 2)] : null;
    return { n: resp.length, median, fast: resp.filter(m => m <= 15).length, waiting: waiting.length, late: waiting.filter(m => m >= STL_LATE_MIN).length, oldest: waiting.length ? Math.max(...waiting) : 0 };
  }, [newLeadContacts, leadFirstCall, stlNow]);
  // Team-wide: which hours of the day actually connect (last 60 days of logged calls).
  const [callBestHours, setCallBestHours] = useState<{ hour: number; rate: number; n: number }[]>([]);
  useEffect(() => {
    if (page !== 'tasks' || tasksSubTab !== 'calls') return;
    let cancelled = false;
    (async () => {
      const since = new Date(Date.now() - 60 * 86_400_000).toISOString();
      const { data } = await supabase.from('crm_client_activities').select('note, created_at').eq('type', 'call').gte('created_at', since).limit(5000);
      if (!cancelled) setCallBestHours(bestHours((data ?? []) as { note: string | null; created_at: string }[]));
    })();
    return () => { cancelled = true; };
  }, [page, tasksSubTab]);
  const dncIds = useMemo(() => new Set(clients.filter(c => isDnc(c)).map(c => c.id)), [clients]);
  const leadPerson = (c: Client): CallListPerson => {
    const ago = (iso: string) => { const m = Math.max(0, Math.round((Date.now() - Date.parse(iso)) / 60000)); return m < 60 ? `${m}m ago` : m < 1440 ? `${Math.round(m / 60)}h ago` : `${Math.round(m / 1440)}d ago`; };
    const biz = (c.business_name ?? '').trim();
    const hot = leadHotness(c);
    return {
      clientId: c.id, reason: `New lead · ${c.lead_source || 'Website'} · ${ago(c.created_at)}${hot.why ? ` · ${hot.why}` : ''}`, heat: hot.heat, view: 'opened', lastCalled: null,
      askFor: leadAsk(c.notes).slice(0, 220), rank: -hot.score * 1e13 + Date.parse(c.created_at),
      business: /^(none|n\/a|na|-)$/i.test(biz) ? '' : biz, contactName: `${c.first_name ?? ''} ${c.last_name ?? ''}`.trim(),
      email: c.email ?? '', phone: c.cell_phone || c.phone || '', category: (c.asset_types ?? []).join(', '), locations: '',
      emailsSent: 0, emailsOpened: 0, opens: 0, clicks: 0, lastOpen: null, lastSent: null, campaignNames: [],
      unsubscribed: !!c.unsubscribed_at, dead: false, notEmailed: false, type: c.type, primaryCampaign: '',
    };
  };
  // New website leads that belong in THIS queue: assigned to the agent, or — if nobody is assigned — Brian's.
  const brianId = useMemo(() => profiles.find(p => (p.email ?? '').toLowerCase() === BRIAN_EMAIL)?.id ?? '', [profiles]);
  const routedLeads = useMemo(() => {
    const me = callViewAgentId || profile?.id || '';
    return newLeadContacts.filter(c => {
      const a = c.assigned_agent_ids ?? [];
      const mine = a.includes(me) || (a.length === 0 && !!brianId && me === brianId);
      return mine && !isDnc(c) && !!(c.cell_phone || c.phone) && !calledLeadIds.has(c.id);
    });
  }, [newLeadContacts, callViewAgentId, profile?.id, brianId, calledLeadIds]);
  const callListMeta = useMemo(() => {
    const m = new Map<string, CallListPerson>();
    for (const p of callListPeople) m.set(`p:${p.clientId}`, p);
    for (const c of routedLeads) if (!m.has(`p:${c.id}`)) m.set(`p:${c.id}`, leadPerson(c));
    return m;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [callListPeople, routedLeads]);
  const clientTypeById = useMemo(() => new Map(clients.map(c => [c.id, c.type as string])), [clients]);
  // Call-backs addressed to the agent whose queue this is (mine = assigned to me or to nobody).
  const callbackMeta = useMemo(() => {
    const m = new Map<string, CallbackRow>();
    const me = callViewAgentId || profile?.id || '';
    for (const cb of callbacks) {
      if (callbackDoneIds.has(cb.id)) continue;
      if (cb.follow_up_assignee && cb.follow_up_assignee !== me) continue;
      if (cb.contact_id && dncIds.has(cb.contact_id)) continue;   // do-not-call
      m.set(`cb:${cb.id}`, cb);
    }
    return m;
  }, [callbacks, callbackDoneIds, callViewAgentId, profile?.id, dncIds]);
  const callbackTasks = useMemo(() => {
    const t0 = today();
    const out: CRMTask[] = [];
    for (const [id, cb] of callbackMeta) {
      const due = new Date(cb.follow_up_due ?? cb.started_at).toLocaleDateString('en-CA');
      if (due > t0 || callSkippedIds.has(id)) continue;     // a later due time sits in the Calling Log until it's due
      const who = cb.contact?.business_name || cb.contact?.name || cb.caller_name || (cb.from_number ?? cb.callback_number ?? cb.to_number ?? 'Caller');
      out.push({ id, client_id: cb.contact_id ?? '', agent_id: cb.follow_up_assignee ?? profile?.id ?? '', type: 'call', title: who, due_date: due, notes: '', completed_at: null, created_at: cb.started_at });
    }
    // Longest-waiting first.
    return out.sort((a, b) => a.created_at.localeCompare(b.created_at));
  }, [callbackMeta, callSkippedIds, profile?.id]);
  const segOfTask = (t: CRMTask): Segment => segmentOf(callListMeta.get(t.id)?.type ?? callbackMeta.get(t.id)?.contact?.type ?? clientTypeById.get(t.client_id));
  const callQueueBase = useMemo(() => {
    const t0 = today();
    if (callListMode !== 'tasks') {
      return callListPeople
        .filter(p => (callPropView === 'opened' ? p.view === 'opened' : callPropView === 'cold' ? p.view === 'cold' : p.view !== 'cold')
          && !!p.phone && !dncIds.has(p.clientId) && !callProspectDoneIds.has(p.clientId) && !callSkippedIds.has(`p:${p.clientId}`))
        .map<CRMTask>(p => ({ id: `p:${p.clientId}`, client_id: p.clientId, agent_id: profile?.id ?? '', type: 'call', title: p.reason, due_date: t0, notes: '', completed_at: null, created_at: '' }));
    }
    if (callOnlyCallbacks) return callbackTasks;
    // Waiting call-backs come first (someone is waiting on us), then the follow-up / call tasks by due date.
    const due = callSource
      .filter(t => (t.type === 'call' || t.type === 'follow_up') && !t.completed_at && t.due_date && t.due_date <= t0 && !callSkippedIds.has(t.id) && !dncIds.has(t.client_id))
      // Oldest due date first; within a day, whoever's been waiting longest.
      .sort((a, b) => a.due_date.localeCompare(b.due_date) || (a.created_at ?? '').localeCompare(b.created_at ?? ''));
    const plain = due.filter(t => !callGroupOf(t));
    const grouped = due.filter(t => callGroupOf(t));
    const size = new Map<string, number>();
    for (const t of grouped) size.set(callGroupOf(t)!, (size.get(callGroupOf(t)!) ?? 0) + 1);
    grouped.sort((a, b) => (size.get(callGroupOf(b)!)! - size.get(callGroupOf(a)!)!) || callGroupOf(a)!.localeCompare(callGroupOf(b)!) || a.title.localeCompare(b.title));
    // New website leads go on top — speed-to-lead: longest-waiting uncalled lead first, then call-backs, then tasks.
    const me = callViewAgentId || profile?.id || '';
    const leadTasks = routedLeads
      .filter(c => !callProspectDoneIds.has(c.id) && !callSkippedIds.has(`p:${c.id}`))
      // Hottest first (see leadHotness); equal heat → whoever has waited longest.
      .sort((a, b) => (leadHotness(b).score - leadHotness(a).score) || a.created_at.localeCompare(b.created_at))
      .map<CRMTask>(c => ({ id: `p:${c.id}`, client_id: c.id, agent_id: me, type: 'call', title: 'New lead', due_date: t0, notes: '', completed_at: null, created_at: c.created_at }));
    return [...leadTasks, ...callbackTasks, ...plain, ...grouped];
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [callSource, callSkippedIds, callListMode, callListPeople, callProspectDoneIds, callPropView, callbackTasks, callOnlyCallbacks, profile?.id, routedLeads, dncIds, callViewAgentId]);
  // Counts per segment for the chips (computed before the segment filter), then the filtered queue.
  const callSegmentCounts = useMemo(() => {
    const n: Record<Segment, number> = { tenant: 0, broker: 0, other: 0 };
    for (const t of callQueueBase) n[segOfTask(t)]++;
    return n;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [callQueueBase, callListMeta, clientTypeById]);
  const callQueueSeg = useMemo(
    () => (callSegment === 'all' ? callQueueBase : callQueueBase.filter(t => segOfTask(t) === callSegment)),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [callQueueBase, callSegment, callListMeta, clientTypeById]);
  // Focus chips (My calls only): what kind of call am I working through right now?
  const focusOf = (t: CRMTask): 'leads' | 'callbacks' | 'overdue' | 'today' =>
    callListMode !== 'tasks' ? 'today' : t.id.startsWith('p:') ? 'leads' : t.id.startsWith('cb:') ? 'callbacks' : (t.due_date && t.due_date < today() && !isListCall(t as never)) ? 'overdue' : 'today';
  const callFocusCounts = useMemo(() => {
    const n = { leads: 0, callbacks: 0, overdue: 0 };
    for (const t of callQueueSeg) { const f = focusOf(t); if (f !== 'today') n[f]++; }
    return n;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [callQueueSeg, callListMode]);
  // A focus whose last call just got done would otherwise strand the agent on a fake "all caught up".
  useEffect(() => {
    if (callFocus !== 'all' && callListMode === 'tasks' && callFocusCounts[callFocus] === 0) setCallFocus('all');
  }, [callFocus, callFocusCounts, callListMode]);
  const callQueue = useMemo(
    () => (callFocus === 'all' || callListMode !== 'tasks' ? callQueueSeg : callQueueSeg.filter(t => focusOf(t) === callFocus)),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [callQueueSeg, callFocus, callListMode]);
  const callUpcomingList = useMemo(() => {
    const t0 = today();
    if (callListMode !== 'tasks') return [] as CRMTask[];
    return callSource
      .filter(t => (t.type === 'call' || t.type === 'follow_up') && !t.completed_at && t.due_date && t.due_date > t0 && !callSkippedIds.has(t.id)
        && (callSegment === 'all' || segmentOf(clientTypeById.get(t.client_id)) === callSegment))
      .sort((a, b) => a.due_date.localeCompare(b.due_date));
  }, [callSource, callSkippedIds, callListMode, callSegment, clientTypeById]);
  // Pick any call from the list; when the selected one is completed/skipped it leaves the queue and
  // the workspace falls back to the top of the list.
  const callCurrent = (callSelectedId ? callQueue.find(t => t.id === callSelectedId) : null) ?? callQueue[0] ?? null;

  // The property list for the "By property" source.
  useEffect(() => {
    if (page !== 'tasks' || tasksSubTab !== 'calls' || callListings.length) return;
    let cancelled = false;
    (async () => {
      try {
        const lh: Record<string, string> = session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {};
        const r = await fetch('/api/crm/listings', { headers: lh });
        const j = await r.json().catch(() => ({}));
        if (!cancelled && r.ok) setCallListings(((j.listings ?? []) as { id: string; name: string }[]).filter(l => l.name).map(l => ({ id: l.id, name: l.name })));
      } catch { /* the dropdown just lacks the property group */ }
    })();
    return () => { cancelled = true; };
  }, [page, tasksSubTab]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (page !== 'tasks' || tasksSubTab !== 'calls' || callListMode !== 'leads:web') return;
    let cancelled = false;
    setCallListLoading(true); setCallSelectedId(null);
    (async () => {
      const ago = (iso: string) => { const m = Math.max(0, Math.round((Date.now() - Date.parse(iso)) / 60000)); return m < 60 ? `${m}m ago` : m < 1440 ? `${Math.round(m / 60)}h ago` : `${Math.round(m / 1440)}d ago`; };
      const people: CallListPerson[] = newLeadContacts.map(leadPerson);
      // Who already got a call: show the date and put the uncalled first.
      const ids = people.map(p => p.clientId);
      const lastCalled = new Map<string, string>();
      for (let i = 0; i < ids.length; i += 150) {
        const { data } = await supabase.from('crm_client_activities').select('client_id, created_at').eq('type', 'call').in('client_id', ids.slice(i, i + 150));
        for (const a of data ?? []) { const prev = lastCalled.get(a.client_id as string); if (!prev || (a.created_at as string) > prev) lastCalled.set(a.client_id as string, a.created_at as string); }
      }
      for (const p of people) p.lastCalled = lastCalled.get(p.clientId) ?? null;
      people.sort((a, b) => Number(!a.phone) - Number(!b.phone) || Number(!!a.lastCalled) - Number(!!b.lastCalled) || a.rank - b.rank);
      if (cancelled) return;
      setCallListPeople(people);
      setCallListInfo(`${people.filter(p => !p.phone).length} without a phone number are hidden here — email them from the contact`);
      setCallListLoading(false);
    })();
    return () => { cancelled = true; };
  }, [page, tasksSubTab, callListMode, callListNonce, newLeadContacts]);

  // People to call out of the marketing. One source of truth: /api/crm/listing-prospects — the same rows (sends,
  // opens, clicks, ask-for, category) the property's Rent Roll "Email Prospects" tab shows, for a property or a campaign.
  useEffect(() => {
    if (page !== 'tasks' || tasksSubTab !== 'calls' || callListMode === 'tasks' || callListMode === 'leads:web') return;
    let cancelled = false;
    setCallListLoading(true); setCallListPeople([]); setCallListInfo(''); setCallSelectedId(null);
    const headers: Record<string, string> = session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {};
    const HEAT_RANK = { hot: 0, warm: 1, cold: 2 } as const;
    (async () => {
      try {
        const qs = callListMode.startsWith('camp:')
          ? `campaign_id=${encodeURIComponent(callListMode.slice(5))}&unit=${businessUnit}`
          : `listing_id=${encodeURIComponent(callListMode.slice(5))}`;
        const r = await fetch(`/api/crm/listing-prospects?${qs}`, { headers });
        const j = await r.json().catch(() => ({}));
        if (!r.ok) throw new Error(j.error ?? 'Could not load the prospects');
        type PP = {
          client_id: string; name: string; business: string; email: string; phone: string; category: string; askFor: string; locations: string;
          emailsSent: number; emailsOpened: number; opens: number; clicks: number; lastOpen: string | null; lastSent: string | null;
          campaignNames?: string[]; unsubscribed: boolean; dead: boolean; notEmailed?: boolean; type?: string; primaryCampaign?: string;
        };
        const people: CallListPerson[] = ((j.prospects ?? []) as PP[]).map(p => {
          const notEmailed = !!p.notEmailed;
          const opened = p.emailsOpened > 0;
          const view: 'opened' | 'emailed' | 'cold' = notEmailed ? 'cold' : opened ? 'opened' : 'emailed';
          const reason = notEmailed ? 'Not emailed yet — cold call'
            : opened ? `Opened ${p.emailsOpened} of ${p.emailsSent} email${p.emailsSent === 1 ? '' : 's'}${p.clicks ? ` · ${p.clicks} click${p.clicks === 1 ? '' : 's'}` : ''}`
            : `Emailed ${p.emailsSent}×, no open yet`;
          const heat: 'hot' | 'warm' | 'cold' = view === 'cold' ? 'cold' : view === 'opened' && (p.clicks > 0 || p.opens >= 2) ? 'hot' : 'warm';
          return {
            clientId: p.client_id, reason, heat, view, lastCalled: null,
            askFor: [p.askFor, p.locations].filter(Boolean).join(' · '),
            rank: HEAT_RANK[heat] * 1e13 - Date.parse(p.lastOpen || '1970-01-01'),
            business: p.business, contactName: p.name, email: p.email, phone: p.phone, category: p.category, locations: p.locations,
            emailsSent: p.emailsSent, emailsOpened: p.emailsOpened, opens: p.opens, clicks: p.clicks, lastOpen: p.lastOpen, lastSent: p.lastSent,
            campaignNames: p.campaignNames ?? [], unsubscribed: p.unsubscribed, dead: p.dead, notEmailed, type: p.type ?? '', primaryCampaign: p.primaryCampaign ?? '',
          };
        });
        // Who has already been called: uncalled first (and a "called Oct 9" tag) so a list worked over several
        // days doesn't send you back to the same people.
        const ids = people.map(p => p.clientId);
        const lastCalled = new Map<string, string>();
        for (let i = 0; i < ids.length; i += 150) {
          const { data } = await supabase.from('crm_client_activities').select('client_id, created_at').eq('type', 'call').in('client_id', ids.slice(i, i + 150));
          for (const a of data ?? []) { const prev = lastCalled.get(a.client_id as string); if (!prev || (a.created_at as string) > prev) lastCalled.set(a.client_id as string, a.created_at as string); }
        }
        for (const p of people) p.lastCalled = lastCalled.get(p.clientId) ?? null;
        // Dialable first (a phone on file), then uncalled before called, then warmest / most recent open.
        people.sort((a, b) => Number(!a.phone) - Number(!b.phone) || Number(!!a.lastCalled) - Number(!!b.lastCalled) || a.rank - b.rank);
        if (cancelled) return;
        setCallListPeople(people);
        setCallListInfo(`${((j.campaigns ?? []) as unknown[]).length} campaign${((j.campaigns ?? []) as unknown[]).length === 1 ? '' : 's'} feeding this list`);
      } catch (e) {
        if (!cancelled) { setCallListInfo(e instanceof Error ? e.message : 'Could not load the list'); }
      } finally {
        if (!cancelled) setCallListLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [page, tasksSubTab, callListMode, callListNonce]); // eslint-disable-line react-hooks/exhaustive-deps

  // Call-backs waiting in the Calling Log → the queue. Re-read whenever the queue is shown or refreshed.
  const loadCallbacks = useCallback(async () => {
    if (!session?.access_token) return;
    try {
      const r = await fetch(`/api/crm/calls?filter=follow_up&days=90&limit=200&business_unit=${businessUnit}`, { headers: { Authorization: `Bearer ${session.access_token}` } });
      const j = await r.json().catch(() => ({}));
      if (r.ok) setCallbacks((j.calls ?? []) as CallbackRow[]);
    } catch { /* the queue still shows tasks */ }
  }, [session?.access_token, businessUnit]);
  useEffect(() => {
    if (page !== 'tasks' || tasksSubTab !== 'calls') return;
    loadCallbacks();
  }, [page, tasksSubTab, loadCallbacks]);

  // The "Today" panel: workspace call-log stats + each agent's calls today (from the contact timeline's call rows).
  useEffect(() => {
    if (page !== 'tasks' || tasksSubTab !== 'calls' || !session?.access_token) return;
    let cancelled = false;
    (async () => {
      const headers = { Authorization: `Bearer ${session.access_token}` };
      const start = new Date(); start.setHours(0, 0, 0, 0);
      const [st, act] = await Promise.all([
        fetch(`/api/crm/calls?stats=1&business_unit=${businessUnit}`, { headers }).then(r => r.json()).catch(() => ({})),
        supabase.from('crm_activity').select('agent_id, client_id, notes').eq('type', 'call').gte('created_at', start.toISOString()).limit(2000),
      ]);
      if (cancelled) return;
      const byAgent: Record<string, { calls: number; talked: number; voicemail: number; none: number }> = {};
      const myLeadSet = new Set<string>(); const leadIds = new Set(newLeadContacts.map(x => x.id));
      for (const a of (act.data ?? []) as { agent_id: string | null; client_id?: string | null; notes: string | null }[]) {
        if (a.agent_id === profile?.id && a.client_id && leadIds.has(a.client_id)) myLeadSet.add(a.client_id);
        if (!a.agent_id) continue;
        const b = (byAgent[a.agent_id] ??= { calls: 0, talked: 0, voicemail: 0, none: 0 });
        const n = a.notes ?? '';
        b.calls++;
        if (/Talked to them/.test(n)) b.talked++; else if (/Left a voicemail/.test(n)) b.voicemail++; else if (/No answer|Wrong number/.test(n)) b.none++;
      }
      { const mine = byAgent[profile?.id ?? ''] ?? { calls: 0, talked: 0, voicemail: 0, none: 0 }; setCallMyDay({ ...mine, leads: myLeadSet.size }); }
      setCallPanel({ stats: (st as { stats?: { today: number; follow_up: number; overdue: number; missed: number; voicemail: number; wrapup: number } }).stats ?? null, byAgent });
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page, tasksSubTab, session?.access_token, businessUnit, callsDoneThisSession]);

  // Open-call counts per agent (admins), for the agent switcher on the Call Queue.
  useEffect(() => {
    const admin = profile?.role === 'admin' || profile?.role === 'super_admin';
    if (page !== 'tasks' || tasksSubTab !== 'calls' || !admin) return;
    let cancelled = false;
    (async () => {
      const { data } = await supabase.from('crm_tasks').select('agent_id')
        .is('completed_at', null).in('type', ['call', 'follow_up']).lte('due_date', today()).limit(5000);
      if (cancelled) return;
      const m: Record<string, number> = {};
      for (const r of data ?? []) if (r.agent_id) m[r.agent_id as string] = (m[r.agent_id as string] ?? 0) + 1;
      setCallAgentCounts(m);
    })();
    return () => { cancelled = true; };
  }, [page, tasksSubTab, profile?.role, callsDoneThisSession, callAssignNonce]);

  // A note typed in the Call Queue is saved when an outcome button is pressed. Moving to another
  // call first used to throw it away. Keep it: on leaving a call that still has an unsaved note,
  // put it on the contact's card as a plain note (clearly labelled as having no outcome).
  const callNoteRef = useRef('');
  callNoteRef.current = callNote;
  const callNoteSavedRef = useRef<string | null>(null);
  useEffect(() => {
    const mine = callCurrent ? { id: callCurrent.id, client_id: callCurrent.client_id, title: callCurrent.title } : null;
    return () => {
      const n = callNoteRef.current.trim();
      if (!mine || !n || !mine.client_id || callNoteSavedRef.current === mine.id) return;
      void logActivity(mine.client_id, 'note', `Call Queue note (no outcome logged) — ${(mine.title || 'call').replace(/^🏢\s*/, '').slice(0, 90)} — ${n}`);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [callCurrent?.id]);

  // Reset the per-call note + follow-up override whenever the active call changes.
  useEffect(() => { setCallNote(''); setCallFollowUpDays(null); setCallTextOpen(false); setCallScriptOpen(false); setCallScriptEdit(false); setCallSnapOpen(false); }, [callCurrent?.id]);

  // Load the current contact's recent activity (attempt history + timeline) for the briefing.
  useEffect(() => {
    const cid = callCurrent?.client_id;
    if (page !== 'tasks' || tasksSubTab !== 'calls' || !cid) { setCallActivities([]); setCallActivitiesClientId(null); return; }
    let cancelled = false;
    (async () => {
      const { data } = await supabase
        .from('crm_client_activities')
        .select('*')
        .eq('client_id', cid)
        .order('created_at', { ascending: false })
        .limit(8);
      if (!cancelled) { setCallActivities((data ?? []) as CRMActivity[]); setCallActivitiesClientId(cid); }
    })();
    return () => { cancelled = true; };
  }, [callCurrent?.client_id, page, tasksSubTab]);

  // Phone: keep the screen awake while you work the queue (a locked phone mid-list is the #1 annoyance).
  useEffect(() => {
    if (windowWidth >= 768 || page !== 'tasks' || tasksSubTab !== 'calls') return;
    type Lock = { release: () => Promise<void> };
    let lock: Lock | null = null; let stopped = false;
    const acquire = async () => {
      try { const l = await (navigator as unknown as { wakeLock?: { request: (t: 'screen') => Promise<Lock> } }).wakeLock?.request('screen'); if (l) lock = l; } catch { /* denied / unsupported */ }
    };
    acquire();
    const onVis = () => { if (document.visibilityState === 'visible' && !stopped) acquire(); };
    document.addEventListener('visibilitychange', onVis);
    return () => { stopped = true; document.removeEventListener('visibilitychange', onVis); lock?.release().catch(() => {}); };
  }, [windowWidth, page, tasksSubTab]);

  // Phone: you tapped Call, went to the dialer, and came back — ask how it went (one tap, then the next call).
  useEffect(() => {
    if (!callDialed) return;
    const back = () => {
      if (document.visibilityState !== 'visible') return;
      if (Date.now() - callDialed.at >= 4000) setCallReturnOpen(true);
    };
    document.addEventListener('visibilitychange', back);
    window.addEventListener('focus', back);
    return () => { document.removeEventListener('visibilitychange', back); window.removeEventListener('focus', back); };
  }, [callDialed]);

  // The shortcuts call these through a ref refreshed every render, so a keypress always runs the
  // current dispositionCall/skipCall (never a closure from the render the listener was bound in).
  const callActs = useRef({ dispositionCall, skipCall });
  callActs.current = { dispositionCall, skipCall };

  // Keyboard shortcuts for power-dialing: C connected, V voicemail, N no answer, S skip.
  useEffect(() => {
    if (page !== 'tasks' || tasksSubTab !== 'calls' || !callCurrent) return;
    function onKey(e: KeyboardEvent) {
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      const el = e.target as HTMLElement | null;
      if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable)) return;
      if (callActionInFlight || !callCurrent) return;
      const k = e.key.toLowerCase();
      if (k === 'c')      { e.preventDefault(); callActs.current.dispositionCall(callCurrent, 'connected'); }
      else if (k === 'v') { e.preventDefault(); callActs.current.dispositionCall(callCurrent, 'voicemail'); }
      else if (k === 'n') { e.preventDefault(); callActs.current.dispositionCall(callCurrent, 'no_answer'); }
      else if (k === 's') { e.preventDefault(); callActs.current.skipCall(callCurrent.id); }
      else if (k === 'w') { e.preventDefault(); callActs.current.dispositionCall(callCurrent, 'wrong_number'); }
      else if (k === 'b') { e.preventDefault(); callActs.current.dispositionCall(callCurrent, 'call_back'); }
      else if (k === 'i') { e.preventDefault(); callActs.current.dispositionCall(callCurrent, 'not_interested'); }
      else if (k === 'j' || k === 'arrowdown' || k === 'k' || k === 'arrowup') {
        // Move through the queue without acting on a call.
        e.preventDefault();
        const i = callQueue.findIndex(t => t.id === callCurrent.id);
        const next = callQueue[Math.min(Math.max(i + (k === 'j' || k === 'arrowdown' ? 1 : -1), 0), callQueue.length - 1)];
        if (next) setCallSelectedId(next.id);
      }
    }
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [page, tasksSubTab, callCurrent, callQueue, callActionInFlight, callNote, callFollowUpDays]);

  // ── Activity Tracking ─────────────────────────────────────────────────────────
  async function loadClientActivities(clientId: string) {
    setActivityLoading(true);
    const { data } = await supabase
      .from('crm_client_activities')
      .select('*')
      .eq('client_id', clientId)
      .order('created_at', { ascending: false });
    setClientActivities((data ?? []) as CRMActivity[]);
    setActivityLoading(false);
  }

  // Hand a contact (usually a brand-new lead) to another agent. The server moves the lead's open call/follow-up
  // tasks and its Prospect deal with it, releases a held lead, and tells the new owner (api/crm/clients/[id]/owner).
  async function reassignContactOwner(c: Client, newOwnerId: string) {
    if (!newOwnerId || newOwnerId === c.agent_id) return;
    const res = await fetch(`/api/crm/clients/${c.id}/owner`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json', ...(session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {}) },
      body: JSON.stringify({ agent_id: newOwnerId }),
    });
    const j = await res.json().catch(() => ({}));
    if (!res.ok) { showToast(j.error || 'Could not reassign this lead'); return; }
    const leadHold = typeof j.lead_hold === 'boolean' ? j.lead_hold : c.lead_hold;
    setClients(prev => prev.map(x => (x.id === c.id ? { ...x, agent_id: newOwnerId, lead_hold: leadHold } : x)));
    setActiveClient(prev => (prev && prev.id === c.id ? { ...prev, agent_id: newOwnerId, lead_hold: leadHold } : prev));
    const moved = [j.tasks ? `${j.tasks} task${j.tasks === 1 ? '' : 's'}` : '', j.deals ? `${j.deals} deal${j.deals === 1 ? '' : 's'}` : ''].filter(Boolean).join(' + ');
    showToast(`✓ Lead reassigned to ${j.owner_name || 'agent'}${moved ? ` — moved ${moved}` : ''}`);
    if (profile) { loadDeals(profile); loadAllTasks(profile); }
    loadClientTasks(c.id);
    loadClientActivities(c.id);
  }

  async function loadClientCampaignSends(clientId: string) {
    const { data } = await supabase
      .from('crm_campaign_sends')
      .select('*, campaign:crm_campaigns(name)')
      .eq('client_id', clientId)
      .order('sent_at', { ascending: false })
      .limit(50);
    setClientCampaignSends(
      (data ?? []).map((s: any) => ({ ...s, campaign_name: s.campaign?.name ?? 'Campaign' }))
    );
  }

  // The campaigns a contact is currently enrolled in — so you can tell at a glance
  // whether they're on our email marketing (vs. the send history in the timeline).
  async function loadClientCampaignEnrollments(clientId: string) {
    const { data } = await supabase
      .from('crm_campaign_enrollments')
      .select('id, campaign_id, active, enrolled_at, campaign:crm_campaigns(name, status, frequency, type)')
      .eq('client_id', clientId)
      .order('enrolled_at', { ascending: false });
    setClientEnrollments(
      (data ?? []).map((e: any) => ({
        id: e.id,
        campaign_id: e.campaign_id,
        active: e.active,
        campaign_name: e.campaign?.name ?? 'Campaign',
        campaign_status: e.campaign?.status,
        campaign_frequency: e.campaign?.frequency,
        campaign_type: e.campaign?.type,
      }))
    );
  }

  async function logActivity(clientId: string, type: CRMActivity['type'], note: string) {
    // Idempotent: an identical touch for the same contact within 30s is a double-click / double-submit, not a
    // second event (the feed had triples of the same call and meeting logged in one second).
    const dupKey = `${clientId}|${type}|${note}`;
    const nowMs = Date.now();
    const seen = recentActivityRef.current.get(dupKey);
    if (seen && nowMs - seen < 30_000) return;
    recentActivityRef.current.set(dupKey, nowMs);
    if (recentActivityRef.current.size > 200) {
      for (const [k, t] of recentActivityRef.current) if (nowMs - t > 30_000) recentActivityRef.current.delete(k);
    }
    const now = new Date().toISOString();
    // Who else was on the call / in the meeting, parsed from the note itself so the
    // tag and the sentence can never drift apart.
    const tagged = parseMentionContactIds(note, clients, profiles).filter(id => id !== clientId);
    const { error } = await supabase.from('crm_client_activities').insert([{
      client_id: clientId,
      agent_id: profile!.id,
      type,
      note,
      tagged_contact_ids: tagged,
    }]);
    // Also roll them onto the contact, so the card's "Also in the room" list covers
    // people tagged in a touch as well as in the notes field.
    if (tagged.length) {
      const cur = clients.find(c => c.id === clientId)?.tagged_contact_ids ?? [];
      const merged = Array.from(new Set([...cur, ...tagged]));
      if (merged.length !== cur.length) {
        await supabase.from('crm_clients').update({ tagged_contact_ids: merged }).eq('id', clientId);
        setClients(prev => prev.map(c => c.id === clientId ? { ...c, tagged_contact_ids: merged } : c));
        setActiveClient(prev => prev && prev.id === clientId ? { ...prev, tagged_contact_ids: merged } : prev);
      }
    }
    if (error) { console.error('Activity log error:', error.message); }
    else {
      const who = parseMentionIds(note, profiles);
      if (who.length) {
        const c = clients.find(x => x.id === clientId);
        createMentionNotifications(who, `@${profile?.first_name} tagged you on a ${type} with ${c ? `${c.first_name} ${c.last_name}`.trim() : 'a contact'}: ${note.length > 90 ? note.slice(0, 90) + '…' : note}`, 'contact', clientId);
      }
    }
    // Always stamp last_touched_at on client regardless of activity insert outcome
    await supabase.from('crm_clients').update({ last_touched_at: now }).eq('id', clientId);
    setClients(prev => prev.map(c => c.id === clientId ? { ...c, last_touched_at: now } : c));
    // Refresh feed if profile modal is open
    if (activeClient?.id === clientId) {
      loadClientActivities(clientId);
      setActiveClient(prev => prev ? { ...prev, last_touched_at: now } : prev);
    }
  }

  // ── @mention notifications ────────────────────────────────────────────────
  async function refreshMentions() {
    if (!profile?.id) return;
    const { data } = await supabase
      .from('crm_notifications')
      .select('*')
      .eq('recipient_id', profile.id)
      .order('created_at', { ascending: false })
      .limit(30);
    // Only touch state when something changed: this runs every minute for the life of the tab, and a
    // fresh array each time re-rendered the entire CRM shell for nothing.
    const next = (data ?? []) as typeof mentions;
    setMentions(prev => (prev.length === next.length && prev.every((p, i) => p.id === next[i].id && p.read_at === next[i].read_at) ? prev : next));
    setMentionsLoaded(true);
  }
  async function loadMentions() {
    if (mentionsLoaded) return;
    await refreshMentions();
  }
  // Community submissions waiting for approval on the Plaza Site (events, news, jobs). Admin-only endpoint; a non-admin simply gets no badge.
  const [plazaPending, setPlazaPending] = useState(0);
  useEffect(() => {
    const token = session?.access_token;
    if (!profile?.id || !token) return;
    const load = () => fetch('/api/crm/plaza-pending', { headers: { Authorization: `Bearer ${token}` } })
      .then(r => (r.ok ? r.json() : null)).then(j => { if (j && typeof j.total === 'number') setPlazaPending(j.total); }).catch(() => {});
    load();
    const t = setInterval(load, 5 * 60 * 1000);
    return () => clearInterval(t);
  }, [profile?.id, session?.access_token]);
  // The bell used to read notifications only when it was clicked, so its badge could never light up
  // for a mention or an assignment. Load once the profile is known and re-check every minute.
  useEffect(() => {
    if (!profile?.id) return;
    refreshMentions();
    // Skip the tick while the tab is hidden, and catch up the moment it is shown again.
    const t = setInterval(() => { if (document.visibilityState === 'visible') refreshMentions(); }, 60_000);
    const onVisible = () => { if (document.visibilityState === 'visible') refreshMentions(); };
    document.addEventListener('visibilitychange', onVisible);
    return () => { clearInterval(t); document.removeEventListener('visibilitychange', onVisible); };
  }, [profile?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  // MentionTextarea reports the mentioned ids on EVERY keystroke while the text contains an @mention,
  // so without a guard one note typed with a tag sent the teammate one notification per character
  // (205 in a day). Notify each person once per entity: in-session memo + a 24h look-back in the DB.
  const mentionedOnce = useRef<Set<string>>(new Set());
  async function createMentionNotifications(ids: string[], message: string, entityType?: string, entityId?: string) {
    if (!ids.length || !profile) return;
    const fresh = ids.filter(id => id !== profile.id && !mentionedOnce.current.has(`${id}|${entityType ?? ''}|${entityId ?? message}`));
    if (!fresh.length) return;
    fresh.forEach(id => mentionedOnce.current.add(`${id}|${entityType ?? ''}|${entityId ?? message}`));
    const since = new Date(Date.now() - 86_400_000).toISOString();
    let dq = supabase.from('crm_notifications').select('recipient_id').eq('sender_id', profile.id).eq('type', 'mention').in('recipient_id', fresh).gte('created_at', since);
    dq = entityId ? dq.eq('entity_id', entityId) : dq.eq('message', message);
    const { data: already } = await dq;
    const alreadySet = new Set((already ?? []).map(r => r.recipient_id as string));
    const rows = fresh
      .filter(id => !alreadySet.has(id))
      .map(id => ({
        recipient_id: id,
        sender_id: profile.id,
        type: 'mention',
        message,
        entity_type: entityType ?? null,
        entity_id: entityId ?? null,
      }));
    if (rows.length) {
      await supabase.from('crm_notifications').insert(rows);
      // The row is the bell; this is the phone alert for it. (An agent can't read rows addressed to someone
      // else, so the server finds the ones we just wrote from who they were for.)
      fetch('/api/crm/push/notify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...(session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {}) },
        body: JSON.stringify({ recipients: rows.map(r => r.recipient_id) }),
      }).catch(() => { /* alerts are best effort */ });
    }
  }

  // A tag in a property / suite / rent-roll note → bell notification for that teammate (once per person per property).
  const noteMention = (ids: string[], message: string, entityType: string, entityId?: string) =>
    createMentionNotifications(ids, `@${profile?.first_name} ${message}`, entityType, entityId);

  useEffect(() => {
    const token = session?.access_token;
    const id = activeClient?.id;
    if (!id || !token) return;
    if (Date.now() - (noteTagsAt.current[id] ?? 0) < 5 * 60_000) return;
    noteTagsAt.current[id] = Date.now();
    fetch(`/api/crm/note-tags?contact_id=${id}`, { headers: { Authorization: `Bearer ${token}` } })
      .then(r => (r.ok ? r.json() : null))
      .then(j => { if (j?.items) setNoteTags(prev => ({ ...prev, [id]: j.items })); })
      .catch(() => { /* the section just doesn't show */ });
  }, [activeClient?.id, session?.access_token]);

  async function markMentionRead(id: string) {
    await supabase.from('crm_notifications').update({ read_at: new Date().toISOString() }).eq('id', id);
    setMentions(prev => prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n));
  }

  async function markAllMentionsRead() {
    const unread = mentions.filter(n => !n.read_at).map(n => n.id);
    if (!unread.length) return;
    await supabase.from('crm_notifications').update({ read_at: new Date().toISOString() }).in('id', unread);
    setMentions(prev => prev.map(n => ({ ...n, read_at: n.read_at ?? new Date().toISOString() })));
  }

  async function toggleDealAgentTag(dealId: string, agentId: string) {
    const deal = deals.find(d => d.id === dealId);
    if (!deal) return;
    const current = deal.assigned_agent_ids ?? [];
    const updated = current.includes(agentId)
      ? current.filter(id => id !== agentId)
      : [...current, agentId];
    const { error } = await supabase.from('crm_deals').update({ assigned_agent_ids: updated }).eq('id', dealId);
    if (error) { showToast('Error: ' + error.message); return; }
    setDeals(prev => prev.map(d => d.id === dealId ? { ...d, assigned_agent_ids: updated } : d));
    if (activeDeal?.id === dealId) setActiveDeal(prev => prev ? { ...prev, assigned_agent_ids: updated } : prev);
    const agentP = profiles.find(p => p.id === agentId);
    const label = agentP ? `${agentP.first_name} ${agentP.last_name}` : 'Agent';
    showToast(updated.includes(agentId) ? `${label} added to deal` : `${label} removed from deal`);
  }

  // ── Client Import ─────────────────────────────────────────────────────────────
  // CSV/data export was removed from the CRM entirely (2026-10-14). Nothing
  // leaves as a file: contacts, commissions, rent rolls and prospect lists stay in the app.
  async function importClients(file: File) {
    try {
      const XLSX = await import('xlsx');
      const buf = await file.arrayBuffer();
      const wb = XLSX.read(buf, { type: 'array' });
      const ws = wb.Sheets[wb.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json<Record<string, string>>(ws);
      let added = 0, errors = 0, dupes = 0;

      // Pre-fetch all existing emails in this business unit for fast dupe checking
      // (paged — a bare select stops at 1000 rows, which left ~70% of existing contacts invisible to the dupe check)
      const existingContacts = await fetchAll<{ email: string | null }>((a, b) => supabase
        .from('crm_clients').select('email').eq('business_unit', businessUnit).order('id').range(a, b));
      const existingEmails = new Set(
        (existingContacts ?? []).map(c => (c.email ?? '').toLowerCase().trim()).filter(Boolean)
      );

      for (const row of rows) {
        const first_name = (row['first_name'] ?? row['First Name'] ?? row['firstname'] ?? '').toString().trim();
        const last_name = (row['last_name'] ?? row['Last Name'] ?? row['lastname'] ?? '').toString().trim();
        const business_name = (row['business_name'] ?? row['Business Name'] ?? row['business'] ?? '').toString().trim();
        const email = (row['email'] ?? row['Email'] ?? '').toString().trim();
        const phone = (row['phone'] ?? row['Phone'] ?? '').toString().trim();
        const cell_phone = (row['cell_phone'] ?? row['Cell Phone'] ?? row['cell'] ?? row['Cell'] ?? '').toString().trim();
        const address = (row['address'] ?? row['Address'] ?? '').toString().trim();
        const city = (row['city'] ?? row['City'] ?? '').toString().trim();
        const state = (row['state'] ?? row['State'] ?? '').toString().trim();
        const zip = (row['zip'] ?? row['ZIP'] ?? row['Zip'] ?? row['postal_code'] ?? '').toString().trim();
        const rawType = (row['type'] ?? row['Type'] ?? 'Buyer').toString().trim();
        const type: Client['type'] = (['Buyer','Seller','Tenant','Landlord/Investor','Agent','Broker'] as string[]).includes(rawType)
          ? rawType as Client['type'] : 'Buyer';
        const brokerage = (row['brokerage'] ?? row['Brokerage'] ?? '').toString().trim();
        const license = (row['license'] ?? row['License'] ?? row['License #'] ?? '').toString().trim();
        const notes = (row['notes'] ?? row['Notes'] ?? '').toString().trim();
        const lead_source = (row['lead_source'] ?? row['Lead Source'] ?? row['source'] ?? row['Source'] ?? '').toString().trim();
        const VALID_ASSET_TYPES = ['Home','Condo','Multi-Family','Land','Industrial','Flex/Warehouse','Retail','Office','Storage'];
        const rawAssetTypes = (row['asset_types'] ?? row['Asset Types'] ?? row['Asset Type'] ?? row['specializes_in'] ?? '').toString();
        const asset_types = rawAssetTypes.split(',').map(s => s.trim()).filter(s => VALID_ASSET_TYPES.includes(s));
        const rawTags = (row['tags'] ?? row['Tags'] ?? '').toString();
        const tags = rawTags ? rawTags.split(',').map(s => s.trim()).filter(Boolean) : [];
        if (!first_name) { errors++; continue; }
        // Skip duplicates — match by email (case-insensitive)
        if (email && existingEmails.has(email.toLowerCase())) { dupes++; continue; }
        const { error } = await supabase.from('crm_clients').insert([{
          first_name, last_name, business_name, email, phone, cell_phone, address, city, state, zip, type, brokerage, license, notes, lead_source, asset_types, tags, agent_id: profile!.id, business_unit: businessUnit,
        }]);
        if (error) { errors++; } else { added++; if (email) existingEmails.add(email.toLowerCase()); }
      }
      await loadClients(profile!, 0, true);
      showToast(`Imported ${added} contact${added !== 1 ? 's' : ''}${dupes > 0 ? ` · ${dupes} duplicate${dupes !== 1 ? 's' : ''} skipped` : ''}${errors > 0 ? ` · ${errors} error${errors !== 1 ? 's' : ''}` : ''}`);
    } catch (err) {
      showToast('Import failed — check file format');
      console.error(err);
    }
    if (importFileRef.current) importFileRef.current.value = '';
  }

  // ── Deal CRUD ────────────────────────────────────────────────────────────────
  // Create a client inline from the New-Deal modal (no leaving the form), add it to
  // the list and select it. Uses the master-contacts endpoint so it isn't duplicated.
  async function createDealClient() {
    const parts = ndNewClient.name.trim().split(/\s+/).filter(Boolean);
    if (!parts.length) { showToast('Enter a name for the new client.'); return; }
    setNdNewClient(s => ({ ...s, saving: true }));
    try {
      const h: Record<string, string> = { 'Content-Type': 'application/json' };
      if (session?.access_token) h.Authorization = `Bearer ${session.access_token}`;
      const res = await fetch('/api/crm/contacts', {
        method: 'POST', headers: h,
        body: JSON.stringify({ first_name: parts[0], last_name: parts.slice(1).join(' ') || null, email: ndNewClient.email || null, phone: ndNewClient.phone || null, type: 'Buyer' }),
      });
      const j = await res.json();
      if (!res.ok || !j.contact) { showToast(j.error || 'Could not create the client.'); setNdNewClient(s => ({ ...s, saving: false })); return; }
      const nc = j.contact;
      const newClient = {
        id: nc.id, agent_id: '', assigned_agent_ids: [], first_name: nc.first_name || '', last_name: nc.last_name || '',
        business_name: nc.business_name || '', email: nc.email || '', extra_emails: [], phone: nc.phone || '', cell_phone: nc.cell_phone || '',
        address: '', city: '', state: '', zip: '', brokerage: nc.brokerage || '', license: '', budget: '', size_range: '', asset_types: [],
        type: (nc.type || 'Buyer'), tags: [], lead_source: 'Deal', notes: '', created_at: new Date().toISOString(),
      } as Client;
      setClients(prev => [newClient, ...prev]);
      setNd(prev => ({ ...prev, client_id: nc.id, client: `${nc.first_name ?? ''} ${nc.last_name ?? ''}`.trim(), client_email: nc.email || '', client_phone: nc.phone || '' }));
      setNdNewClient({ show: false, name: '', email: '', phone: '', saving: false });
    } catch { showToast('Could not create the client.'); setNdNewClient(s => ({ ...s, saving: false })); }
  }

  async function createDeal() {
    if (!nd.client_id) { showToast('Please select a client first.'); return; }
    setSaving(true);
    const { data: created, error } = await supabase.from('crm_deals').insert([{
      client_id: nd.client_id,
      client: nd.client,
      client_email: nd.client_email,
      client_phone: nd.client_phone,
      type: nd.type,
      property: nd.property,
      value: nd.value,
      notes: nd.notes,
      agent_id: profile!.id,
      stage: 'Prospect',
      last_touch: today(),
      business_unit: businessUnit,
    }]).select('id').single();
    if (error) { showToast('Error: ' + error.message); setSaving(false); return; }
    // The database marks a super admin's new deals private automatically; unticking the box lifts it.
    if (isSuperAdmin && !ndPrivate && created?.id) await supabase.from('crm_deals').update({ is_restricted: false }).eq('id', created.id);
    // Attach the selected closing-form packet(s) to the new deal.
    let attached = 0;
    const pkts = FORM_PACKETS.filter(p => ndPackets.includes(p.key));
    if (created?.id && pkts.length) {
      let forms = crmForms;
      if (!forms.length) {
        try { const r = await authGet(`/api/crm/forms?business_unit=${businessUnit}`); const j = await r.json(); forms = j.forms ?? []; setCrmForms(forms); } catch { /* ignore */ }
      }
      for (const pkt of pkts) attached += await attachPacketToDeal(created.id, pkt, forms);
    }
    showToast(attached ? `Deal created — ${attached} form${attached === 1 ? '' : 's'} attached` : 'Deal created: ' + nd.client);
    setNd({ client_id: '', client: '', client_email: '', client_phone: '', type: 'Buyer Purchase', property: '', value: 0, notes: '' });
    setNdPackets([]);
    setShowAddDeal(false);
    loadDeals(profile!);
    setSaving(false);
  }

  async function updateDeal(id: string, fields: Partial<Deal>) {
    const { error } = await supabase.from('crm_deals').update({ ...fields, last_touch: today() }).eq('id', id);
    if (error) { showToast("Couldn't save that change: " + (error.message || 'permission denied')); loadDeals(profile!); return; }
    setDeals(prev => prev.map(d => d.id === id ? { ...d, ...fields, last_touch: today() } : d));
    if (activeDeal?.id === id) setActiveDeal(prev => prev ? { ...prev, ...fields } : prev);
  }

  async function setStage(deal: Deal, stage: string) {
    // Clicking the stage it is already in is not a move: no touch, no toast, no "Stage moved" log line
    // (the activity feed carried runs of identical "Stage moved to LOI" entries from exactly this).
    if (deal.stage !== stage) {
      await updateDeal(deal.id, { stage });
      showToast('Stage → ' + stage);
      if (deal.client_id) {
        logActivity(deal.client_id, 'deal_update', `Stage moved to "${stage}"${deal.property ? ` — ${deal.property}` : ''}`);
      }
    }
    if (stage === 'Closed') triggerClosedPrompt({ ...deal, stage });
    if (stage === 'Lost') triggerLostPrompt({ ...deal, stage });
  }

  async function deleteDeal(id: string) {
    // Say exactly what goes with the deal. Its emails, documents, forms and meetings are
    // deleted WITH it (cascade); signature requests are kept but lose their deal link.
    const target = deals.find(d => d.id === id);
    const label = target ? [target.client, target.property].filter(Boolean).join(' — ') : '';
    const countOf = async (table: string) => {
      const { count } = await supabase.from(table).select('id', { count: 'exact', head: true }).eq('deal_id', id);
      return count ?? 0;
    };
    const [emails, docA, docB, forms, meetings, envelopes] = await Promise.all(
      ['crm_deal_emails', 'crm_deal_docs', 'crm_docs', 'crm_deal_forms', 'crm_deal_meetings', 'crm_envelopes'].map(countOf),
    );
    const plural = (n: number, w: string) => `${n} ${w}${n === 1 ? '' : 's'}`;
    const goes = [
      emails && plural(emails, 'email'),
      docA + docB && plural(docA + docB, 'document'),
      forms && plural(forms, 'form'),
      meetings && plural(meetings, 'meeting'),
    ].filter(Boolean);
    const msg =
      `Delete ${label ? `“${label}”` : 'this deal'}?\n\n` +
      (goes.length ? `This also deletes its ${goes.join(', ')}.` : 'Nothing else is attached to it.') +
      (envelopes ? `\n${plural(envelopes, 'signature request')} will be kept but unlinked from the deal.` : '') +
      '\n\nThis cannot be undone.';
    if (!confirm(msg)) return;
    // .select() so a delete that matched nothing (not allowed to see/remove it) is
    // caught — otherwise the card vanished and said "deleted" while the deal stayed.
    const { data: removed, error } = await supabase.from('crm_deals').delete().eq('id', id).select('id');
    if (error || !removed || removed.length === 0) {
      showToast('Could not delete the deal — nothing was changed.');
      return;
    }
    setDeals(prev => prev.filter(d => d.id !== id));
    setActiveDeal(null);
    if (typeof window !== 'undefined') sessionStorage.removeItem('activeDealId');
    showToast('Deal deleted.');
  }

  // ── Email log ────────────────────────────────────────────────────────────────
  async function logEmail(deal: Deal) {
    if (!ne.subject.trim()) { showToast('Subject required.'); return; }
    const ag = profile!;
    const entry = {
      deal_id: deal.id,
      direction: ne.direction,
      from_email: ne.direction === 'sent' ? ag.email : deal.client_email,
      to_email: ne.direction === 'sent' ? deal.client_email : ag.email,
      subject: ne.subject,
      body: ne.body,
      email_date: ne.email_date,
    };
    const { error } = await supabase.from('crm_deal_emails').insert([entry]);
    if (error) { showToast('Error: ' + error.message); return; }
    await updateDeal(deal.id, { last_touch: today() });
    setNe({ direction: 'sent', subject: '', body: '', email_date: today() });
    loadDealEmails(deal.id);
    showToast('Email logged.');
    if (deal.client_id) {
      logActivity(deal.client_id, 'email', `${ne.direction === 'sent' ? 'Sent' : 'Received'} email: ${ne.subject}`);
    }
  }

  // ── Invite agent ─────────────────────────────────────────────────────────────
  async function inviteAgent() {
    // Creating an account is super-admin-only, same as granting admin above.
    // The route enforces it; this is so the answer arrives as a sentence
    // rather than a 403.
    if (!isSuperAdmin) { showToast('Only a super admin can invite agents.'); return; }
    if (!inv.email || !inv.first_name || !inv.last_name) { showToast('Email and name required.'); return; }
    setSaving(true);
    const res = await fetch('/api/crm/invite', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...inv, firstName: inv.first_name, lastName: inv.last_name, business_unit: businessUnit }),
    });
    const json = await res.json();
    if (!res.ok) { showToast('Error: ' + json.error); } else {
      showToast(`Invite sent to ${inv.email}`);
      setInv({ email: '', first_name: '', last_name: '', phone: '', license: '' });
      setShowInvite(false);
      loadProfiles();
    }
    setSaving(false);
  }

  // ── Reset agent password ──────────────────────────────────────────────────────
  async function resetAgentPassword(email: string, firstName: string) {
    const res = await fetch('/api/crm/reset-password', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(session?.access_token ? { 'Authorization': `Bearer ${session.access_token}` } : {}) },
      body: JSON.stringify({ email, firstName }),
    });
    const json = await res.json();
    if (!res.ok) showToast('Error: ' + json.error);
    else showToast(`Password reset sent to ${email}`);
  }

  // ── Delete agent ──────────────────────────────────────────────────────────────
  async function updateAgentRole(userId: string, firstName: string, newRole: 'admin' | 'agent') {
    // Granting/revoking admin is super-admin-only — stops an admin (e.g. Brian)
    // from promoting himself/others or demoting the super admin. This goes through
    // the server route (service-role key): a direct browser write cannot do it,
    // because RLS restricts crm_profiles writes to the caller's OWN row, so
    // updating someone else's row silently changed 0 rows and "didn't stick".
    if (!isSuperAdmin) { showToast('Only a super admin can change admin access.'); return; }
    const action = newRole === 'admin' ? `Make ${firstName} an admin?` : `Remove admin access from ${firstName}?`;
    if (!confirm(action)) return;
    const res = await fetch(`/api/crm/profiles/${userId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json', ...(session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {}) },
      body: JSON.stringify({ role: newRole }),
    });
    const json = await res.json().catch(() => ({}));
    if (!res.ok) { showToast('Error: ' + (json.error || 'could not change role')); return; }
    showToast(`${firstName} is now ${newRole === 'admin' ? 'an Admin' : 'an Agent'}`);
    loadProfiles();
  }

  async function deleteAgent(userId: string, firstName: string, lastName: string) {
    if (!isSuperAdmin) { showToast('Only a super admin can remove agents.'); return; }
    if (!confirm(`Remove ${firstName} ${lastName} from the CRM? This cannot be undone.`)) return;
    const res = await fetch('/api/crm/delete-agent', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId }),
    });
    const json = await res.json();
    if (!res.ok) showToast('Error: ' + json.error);
    else { showToast(`${firstName} ${lastName} removed`); loadProfiles(); }
  }

  async function saveAgentProfile() {
    if (!editingAgentId) return;
    setEditAgentSaving(true);
    const res = await fetch(`/api/crm/profiles/${editingAgentId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(editAgentForm),
    });
    const json = await res.json();
    if (!res.ok) { showToast('Error: ' + json.error); }
    else {
      showToast('Profile updated ✓');
      setEditingAgentId(null);
      loadProfiles();
    }
    setEditAgentSaving(false);
  }

  // ── Disconnect Gmail account ──────────────────────────────────────────────────
  async function disconnectGmailAccount(connectionId: string) {
    const res = await fetch('/api/gmail/status', {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session!.access_token}` },
      body: JSON.stringify({ connectionId, userId: session!.user.id }),
    });
    const json = await res.json();
    if (!res.ok || json.error) {
      showToast('Failed to disconnect — please try again');
      return;
    }
    const updated = gmailAccounts.filter(a => a.id !== connectionId);
    setGmailAccounts(updated);
    if (updated.length === 0) setGmailConnected(false);
    showToast('Account disconnected');
  }

  // ── Gmail sync ───────────────────────────────────────────────────────────────
  async function syncGmail(deal: Deal) {
    if (!deal.client_email) { showToast('No client email on this deal'); return; }
    setSyncing(true);
    const res = await fetch('/api/gmail/sync', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session!.access_token}` },
      body: JSON.stringify({ userId: deal.agent_id ?? session!.user.id, dealId: deal.id, clientEmail: deal.client_email }),
    });
    const json = await res.json();
    if (!res.ok) showToast('Sync error: ' + (json.error ?? res.status) + (json.debug ? ' | ' + JSON.stringify(json.debug) : ''));
    else { showToast(`Synced ${json.synced} new email${json.synced !== 1 ? 's' : ''} from Gmail`); loadDealEmails(deal.id); }
    setSyncing(false);
  }

  // Clear Gmail-synced emails for a deal and re-sync from scratch
  async function clearAndResync(deal: Deal) {
    if (!deal.client_email) { showToast('No client email on this deal'); return; }
    if (!confirm('This will remove all Gmail-synced emails for this deal and re-sync. Manually logged emails are kept. Continue?')) return;
    setSyncing(true);
    // Delete only Gmail-synced rows (gmail_message_id is set), keep manual logs
    await supabase
      .from('crm_deal_emails')
      .delete()
      .eq('deal_id', deal.id)
      .not('gmail_message_id', 'is', null);

    // Now re-sync with the corrected query
    const res = await fetch('/api/gmail/sync', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session!.access_token}` },
      body: JSON.stringify({ userId: deal.agent_id ?? session!.user.id, dealId: deal.id, clientEmail: deal.client_email }),
    });
    const json = await res.json();
    if (!res.ok) showToast('Sync error: ' + json.error);
    else { showToast(`Re-synced ${json.synced} email${json.synced !== 1 ? 's' : ''} between you and ${deal.client_email}`); loadDealEmails(deal.id); }
    setSyncing(false);
  }

  // ── Contact-level Gmail sync & send ─────────────────────────────────────────
  async function syncGmailForContact(client: Client) {
    if (!client.email) { showToast('No email on this contact'); return; }
    setSyncing(true);
    const res = await fetch('/api/gmail/sync', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session!.access_token}` },
      body: JSON.stringify({ userId: client.agent_id ?? session!.user.id, clientId: client.id, clientEmail: client.email }),
    });
    const json = await res.json();
    if (!res.ok) showToast('Sync error: ' + (json.error ?? res.status) + (json.debug ? ' | ' + JSON.stringify(json.debug) : ''));
    else { showToast(`Synced ${json.synced} new email${json.synced !== 1 ? 's' : ''}`); loadContactEmails(client.id); }
    setSyncing(false);
  }

  async function sendGmailEmailToContact(client: Client) {
    if (!composeSubject.trim()) { showToast('Subject is required'); return; }
    setComposeSending(true);
    try {
      const messageHtml = contactComposeBodyRef.current?.innerHTML ?? '';
      const sig = profile?.email_signature ? `<br/><br/><div class="gmail_signature">${profile.email_signature}</div>` : '';
      const fullBody = profile?.email_signature ? `${messageHtml}${sig}` : messageHtml;
      const agentName = `${profile!.first_name} ${profile!.last_name}`;
      const threadingParams = replyToContactEmail ? {
        threadId: replyToContactEmail.gmail_thread_id,
        inReplyTo: replyToContactEmail.rfc_message_id,
      } : {};
      const attachments = await Promise.all(
        composeAttachments.map(file => new Promise<{ name: string; mimeType: string; data: string }>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve({ name: file.name, mimeType: file.type || 'application/octet-stream', data: (reader.result as string).split(',')[1] });
          reader.onerror = reject;
          reader.readAsDataURL(file);
        }))
      );
      const res = await fetch('/api/gmail/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session!.access_token}` },
        body: JSON.stringify({ userId: session!.user.id, clientId: client.id, to: [client.email, composeMoreTo].filter(Boolean).join(', '), cc: composeCc, individual: composeIndividual, subject: composeSubject, body: fullBody, agentName, ccAgentIds: [], attachments, ...threadingParams }),
      });
      const json = await res.json();
      if (!res.ok) { showToast('Send failed: ' + (json.error ?? res.status)); }
      else {
        showToast('Email sent');
        setShowContactCompose(false);
        setReplyToContactEmail(null);
        setReplyingToThreadKey(null);
        clearContactComposeBody();
        setComposeSubject(''); setComposeMoreTo(''); setComposeCc('');
        setComposeAttachments([]);
        loadContactEmails(client.id);
        logActivity(client.id, 'email', `Sent email: ${composeSubject}`);
      }
    } catch (err) {
      showToast('Send error — check console');
      console.error(err);
    }
    setComposeSending(false);
  }

  // ── Gmail compose & send ─────────────────────────────────────────────────────
  async function sendGmailEmail(deal: Deal) {
    if (!composeSubject.trim()) { showToast('Subject is required'); return; }
    setComposeSending(true);
    try {
      const agentName = `${profile!.first_name} ${profile!.last_name}`;
      const sig = profile?.email_signature ?? '';
      const messageHtml = composeBodyRef.current?.innerHTML ?? '';
      const fullBody = sig
        ? `${messageHtml}<br/><br/><div class="gmail_signature">${sig}</div>`
        : messageHtml || '&nbsp;';
      const threadingParams = replyToEmail ? {
        threadId: replyToEmail.gmail_thread_id,
        inReplyTo: replyToEmail.rfc_message_id,
      } : {};

      // Convert attachments to base64
      const attachments = await Promise.all(
        composeAttachments.map(file => new Promise<{ name: string; mimeType: string; data: string }>((resolve, reject) => {
          const reader = new FileReader();
          reader.readAsDataURL(file);
          reader.onload = () => resolve({ name: file.name, mimeType: file.type || 'application/octet-stream', data: (reader.result as string).split(',')[1] });
          reader.onerror = () => reject(new Error(`Failed to read ${file.name}`));
        }))
      );

      const res = await fetch('/api/gmail/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session!.access_token}` },
        body: JSON.stringify({ userId: session!.user.id, dealId: deal.id, to: [deal.client_email, composeMoreTo].filter(Boolean).join(', '), cc: composeCc, individual: composeIndividual, subject: composeSubject, body: fullBody, agentName, ccAgentIds: deal.assigned_agent_ids ?? [], attachments, ...threadingParams }),
      });
      let j: any = {};
      try { j = await res.json(); } catch {}
      if (!res.ok) {
        showToast('Send failed: ' + (j.error || `HTTP ${res.status}`));
      } else {
        showToast('✉️ Email sent via Gmail');
        setShowCompose(false);
        setComposeSubject(''); setComposeMoreTo(''); setComposeCc('');
        clearComposeBody();
        setReplyToEmail(null);
        setComposeAttachments([]);
        loadDealEmails(deal.id);
        if (deal.client_id) logActivity(deal.client_id, 'email', `Sent email: ${composeSubject}`);
      }
    } catch (err) {
      showToast('Send failed: ' + String(err));
    } finally {
      setComposeSending(false);
    }
  }

  // ── Campaigns ─────────────────────────────────────────────────────────────────
  // The list's own counts skip Gmail (replies, and our replies back) to stay fast.
  // The call-list endpoint includes it, so once it answers (a few seconds), its
  // numbers replace the quick ones on the summary card and the campaign rows —
  // the card, the badges and the list then all agree.
  const engagementRefreshed = useRef(false);
  async function refreshEngagementCounts() {
    engagementRefreshed.current = true;
    try {
      const r = await fetch('/api/campaigns/engagement', { headers: session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {} });
      if (!r.ok) return;
      const j = await r.json();
      const people = (j.people ?? []) as { contacted_at: string | null; campaigns: { id: string }[] }[];
      const by = new Map<string, { engaged: number; to_call: number }>(((j.campaigns ?? []) as { id: string }[]).map(c => [c.id, { engaged: 0, to_call: 0 }]));
      for (const p of people) for (const c of p.campaigns) {
        const b = by.get(c.id); if (!b) continue;
        b.engaged++; if (!p.contacted_at) b.to_call++;
      }
      setEngagementTotals({ engaged: people.length, to_call: people.filter(p => !p.contacted_at).length });
      setCampaigns(prev => prev.map(c => { const b = by.get(c.id); return b ? { ...c, engaged_count: b.engaged, to_call_count: b.to_call } : c; }));
    } catch { /* keep the quick counts */ }
  }

  // quick: the first load on sign-in. The Gmail-inclusive engagement pass (slow — it reads
  // Gmail) only matters once you are on Marketing, and every path into Marketing reloads
  // campaigns without `quick`, so it runs then.
  async function loadCampaigns(opts?: { quick?: boolean }) {
    setCampaignLoading(true);
    try {
      const res = await fetch(`/api/campaigns?unit=${businessUnit}`, { headers: session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {} });
      const j = await res.json();
      if (res.ok) {
        setCampaigns(j.campaigns ?? []); setEngagementTotals(j.engagement_totals ?? null); if (!opts?.quick) refreshEngagementCounts();
        if (!campaignFilterChosen.current && !((j.campaigns ?? []) as { status: string }[]).some(c => c.status === 'active')) setCampaignFilter('all');   // nothing active: open on All, not an empty page
      }
      else { showToast(`Could not load campaigns: ${j.error ?? res.status}`); }
    } catch (err) {
      showToast('Network error loading campaigns');
    } finally {
      setCampaignLoading(false);
    }
  }

  // The list endpoint omits email HTML (has_body says one exists). Open, preview and edit
  // load it here, once, and merge it into the list so it is not fetched again.
  const bodyLoads = useRef(new Map<string, Promise<string | null>>());
  async function ensureCampaignBody(c: Campaign): Promise<Campaign> {
    if (c.type !== 'email' || c.email_body !== undefined) return c;
    let p = bodyLoads.current.get(c.id);
    if (!p) {
      p = fetch(`/api/campaigns/${c.id}`, { headers: session?.access_token ? { Authorization: `Bearer ${session.access_token}` } : {} })
        .then(r => r.ok ? r.json() : Promise.reject(new Error(String(r.status))))
        .then(j => (j.campaign?.email_body as string | null | undefined) ?? '');
      bodyLoads.current.set(c.id, p);
      p.catch(() => bodyLoads.current.delete(c.id));
    }
    try {
      const body = await p;
      const full: Campaign = { ...c, email_body: body ?? '' };
      setCampaigns(prev => prev.map(x => x.id === c.id ? { ...x, email_body: body ?? '' } : x));
      return full;
    } catch {
      showToast('Could not load the email body — try again');
      throw new Error('campaign body unavailable');
    }
  }

  // Anything that renders a campaign's email (detail view, preview, "view sent email")
  // gets its body here as soon as that campaign is on screen.
  const viewSendCampaignId = viewCampaignSendModal?.send?.campaign_id ?? null;
  useEffect(() => {
    const need = (c: Campaign | null | undefined) => !!c && c.type === 'email' && c.has_body && c.email_body === undefined;
    if (need(activeCampaign)) {
      ensureCampaignBody(activeCampaign!)
        .then(full => setActiveCampaign(prev => prev && prev.id === full.id ? { ...prev, email_body: full.email_body } : prev))
        .catch(() => {});
    }
    if (need(previewCampaign)) {
      ensureCampaignBody(previewCampaign!)
        .then(full => setPreviewCampaign(prev => prev && prev.id === full.id ? { ...prev, email_body: full.email_body } : prev))
        .catch(() => {});
    }
    const sent = viewSendCampaignId ? campaigns.find(c => c.id === viewSendCampaignId) : null;
    if (need(sent)) ensureCampaignBody(sent!).catch(() => {});
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeCampaign?.id, activeCampaign?.email_body, previewCampaign?.id, previewCampaign?.email_body, viewSendCampaignId, campaigns.length]);

  async function loadCampaignProjects() {
    const { data } = await supabase.from('crm_campaign_projects').select('*').order('created_at', { ascending: true });
    setCampaignProjects(data ?? []);
    // Everything starts closed — with a dozen projects open at once the page was a
    // wall of campaign rows. The collapsed header still shows the name, the campaign
    // count and when it last sent, so the summary is there without the noise.
    setExpandedProjects(new Set());
  }

  async function createCampaignProject() {
    if (!newProjectName.trim()) return;
    const { data } = await supabase.from('crm_campaign_projects').insert({ name: newProjectName.trim(), description: newProjectDesc.trim(), color: newProjectColor, created_by: session!.user.id }).select().single();
    if (data) {
      setCampaignProjects(prev => [...prev, data]);
      setExpandedProjects(prev => new Set([...prev, data.id]));
    }
    setNewProjectName(''); setNewProjectDesc(''); setNewProjectColor('#c9922c'); setShowAddProject(false);
  }

  async function updateCampaignProject() {
    if (!editingProject) return;
    await supabase.from('crm_campaign_projects').update({ name: editingProject.name, description: editingProject.description, color: editingProject.color }).eq('id', editingProject.id);
    setCampaignProjects(prev => prev.map(p => p.id === editingProject.id ? editingProject : p));
    setEditingProject(null);
  }

  async function deleteCampaignProject(id: string) {
    if (!confirm('Delete this project? Campaigns inside will become ungrouped.')) return;
    await supabase.from('crm_campaign_projects').delete().eq('id', id);
    setCampaignProjects(prev => prev.filter(p => p.id !== id));
    setCampaigns(prev => prev.map(c => c.project_id === id ? { ...c, project_id: null } : c));
  }

  async function assignCampaignToProject(campaignId: string, projectId: string | null) {
    await fetch(`/api/campaigns/${campaignId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session!.access_token}` }, body: JSON.stringify({ project_id: projectId }) });
    setCampaigns(prev => prev.map(c => c.id === campaignId ? { ...c, project_id: projectId } : c));
  }

  // Duplicate: open the builder pre-filled from an existing campaign, as a NEW draft (no send date, nobody emailed). The builder
  // offers to carry the recipient list over too. It goes through the builder rather than saving straight away because a one-time
  // campaign needs a send date, and the copy should be reviewed (name, subject, date) before it exists.
  async function startDuplicate(camp: Campaign) {
    let full: Campaign;
    try { full = await ensureCampaignBody(camp); } catch { return; }
    let count = 0, personalised = 0;
    try {
      const r = await fetch(`/api/campaigns/${camp.id}/enrollments`, { headers: { Authorization: `Bearer ${session!.access_token}` } });
      if (r.ok) {
        const rows = ((await r.json()).enrollments ?? []) as { client: { unsubscribed_at?: string | null } | null; merge_fields: Record<string, unknown> | null }[];
        const usable = rows.filter(e => e.client && !e.client.unsubscribed_at);
        count = usable.length; personalised = usable.filter(e => Object.keys(e.merge_fields ?? {}).length > 0).length;
      }
    } catch { /* the copy still works without the recipient count */ }
    setActiveCampaign(null);
    setCampaignListingId((full as { listing_id?: string | null }).listing_id ?? '');
    setNewCampaign({ name: `${full.name} (copy)`, description: full.description, type: full.type, frequency: full.frequency, send_date: '', send_time: full.send_time ?? '08:00', send_day_of_month: full.send_day_of_month != null ? String(full.send_day_of_month) : '', status: 'draft', email_subject: full.email_subject ?? '', email_body: full.email_body ?? '', sms_body: full.sms_body ?? '', sender_agent_id: full.sender_agent_id ?? '', project_id: full.project_id ?? '', hold_risky_addresses: !!full.hold_risky_addresses, copy_from: camp.id, copy_from_name: camp.name, copy_count: count, copy_personalised: personalised, copy_recipients: false });
    setCampaignView('builder');
  }

  async function saveCampaign() {
    // Always grab the freshest content — editor ref if mounted, otherwise state
    const latestEmailBody = (emailEditorMode === 'rich' && emailEditorRef.current?.innerHTML)
      || newCampaign.email_body;
    setSaving(true);
    try {
      // Going live from the editor runs the pre-send check first: save with the
      // current status, then the check activates it (or explains why it can't).
      const goingLive = newCampaign.status === 'active' && activeCampaign?.status !== 'active';
      const body: Record<string, unknown> = { ...newCampaign, ...(goingLive ? { status: activeCampaign?.status ?? 'draft' } : {}), listing_id: campaignListingId || null, email_body: latestEmailBody, created_by: session!.user.id, business_unit: businessUnit };
      // List rows carry no email HTML. If this campaign's body never loaded, leave it alone
      // rather than saving an empty one over it.
      if (activeCampaign && activeCampaign.email_body === undefined && activeCampaign.has_body && !String(latestEmailBody ?? '').trim()) delete body.email_body;
      const url = activeCampaign ? `/api/campaigns/${activeCampaign.id}` : '/api/campaigns';
      const method = activeCampaign ? 'PATCH' : 'POST';
      const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session!.access_token}` }, body: JSON.stringify(body) });
      const j = await res.json();
      if (!res.ok) { showToast('Error: ' + (j.error ?? 'Save failed')); }
      else {
        let copied = 0;
        if (!activeCampaign && newCampaign.copy_from && newCampaign.copy_recipients && j.campaign?.id) {
          try {
            const r = await fetch(`/api/campaigns/${newCampaign.copy_from}/enrollments`, { headers: { Authorization: `Bearer ${session!.access_token}` } });
            const ids = r.ok ? (((await r.json()).enrollments ?? []) as { client_id: string; client: { unsubscribed_at?: string | null } | null }[]).filter(e => e.client && !e.client.unsubscribed_at).map(e => e.client_id) : [];
            if (ids.length) {
              const er = await fetch(`/api/campaigns/${j.campaign.id}/enrollments`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${session!.access_token}` }, body: JSON.stringify({ client_ids: ids, enrolled_by: session!.user.id }) });
              if (er.ok) copied = ((await er.json()).enrolled as number) ?? ids.length;
            }
          } catch { /* the copy exists; recipients can be added from Manage */ }
        }
        showToast(activeCampaign ? 'Campaign updated' : copied ? `Campaign duplicated with ${copied} recipient${copied !== 1 ? 's' : ''} — still a draft` : newCampaign.copy_from ? 'Campaign duplicated as a draft' : 'Campaign created');
        if (goingLive && j.campaign?.id) setPreflightFor([{ id: j.campaign.id, name: j.campaign.name ?? newCampaign.name, type: j.campaign.type ?? newCampaign.type }]);
        setEmailEditorMode('rich');
        setCampaignView('list');
        setActiveCampaign(null);
        setNewCampaign({ name: '', description: '', type: 'email', frequency: 'monthly', send_date: '', send_time: '08:00', send_day_of_month: '', status: 'draft', email_subject: '', email_body: '', sms_body: '', sender_agent_id: '', project_id: '' });
        loadCampaigns();
      }
    } catch (err) {
      showToast('Network error — please try again');
    } finally {
      setSaving(false);
    }
  }

  async function deleteCampaign(id: string) {
    if (!confirm('Delete this campaign? This cannot be undone.')) return;
    await fetch(`/api/campaigns/${id}`, { method: 'DELETE' });
    showToast('Campaign deleted');
    setActiveCampaign(null);
    setCampaignView('list');
    loadCampaigns();
  }

  // Set a campaign's status straight from the list (activate arms it — the PATCH route
  // back-fills next_send_at on the enrollments; pause stops it). Cookie-authed like the
  // detail view's Activate button, with the Bearer token too when we have a session.
  async function setCampaignStatusFromList(id: string, status: 'active' | 'paused', name?: string) {
    if (status === 'active') { setPreflightFor([{ id, name: name ?? 'Campaign', type: campaigns.find(c => c.id === id)?.type }]); return; }
    setBusyCampaignId(id);
    try {
      await fetch(`/api/campaigns/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json', ...(session ? { Authorization: `Bearer ${session.access_token}` } : {}) },
        body: JSON.stringify({ status }),
      });
      showToast('Campaign paused');
      await loadCampaigns();
    } finally {
      setBusyCampaignId(null);
    }
  }

  // Bulk status change for the multi-select action bar.
  async function bulkSetCampaignStatus(ids: string[], status: 'active' | 'paused') {
    if (ids.length === 0) return;
    if (status === 'active') { setPreflightFor(ids.map(id => { const c = campaigns.find(x => x.id === id); return { id, name: c?.name ?? 'Campaign', type: c?.type }; })); return; }
    for (const id of ids) {
      await fetch(`/api/campaigns/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json', ...(session ? { Authorization: `Bearer ${session.access_token}` } : {}) },
        body: JSON.stringify({ status }),
      });
    }
    showToast(`${ids.length} campaign${ids.length !== 1 ? 's' : ''} paused`);
    setSelectedCampaignIds(new Set());
    await loadCampaigns();
  }

