  // Every campaign enrollment in the current workspace, grouped by contact — one query that
  // powers the Campaigns column on the contacts list (rather than a query per row).
  async function loadAllEnrollments() {
    // paged — the 1000-row cap used to hide ~27% of enrollments from the Contacts "Campaigns" column
    const data = await fetchAll<any>((a, b) => supabase
      .from('crm_campaign_enrollments')
      .select('client_id, active, campaign:crm_campaigns!inner(name, status, business_unit)')
      .eq('campaign.business_unit', businessUnit).order('id').range(a, b));
    const map: Record<string, { campaign_name: string; active: boolean; campaign_status?: string }[]> = {};
    for (const e of (data ?? []) as any[]) {
      if (!e.client_id) continue;
      (map[e.client_id] ??= []).push({ campaign_name: e.campaign?.name ?? 'Campaign', active: e.active, campaign_status: e.campaign?.status });
    }
    setEnrollmentsByClient(map);
  }

  async function saveSmartList() {
    if (!newListName.trim()) { showToast('Enter a list name'); return; }
    const filters: Record<string, any> = {};
    if (contactTypeFilter) filters.type = contactTypeFilter;
    if (contactTagFilter) filters.tag = contactTagFilter;
    if (contactSourceFilter) filters.lead_source = contactSourceFilter;
    const res = await fetch('/api/smart-lists', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: newListName.trim(), filters, created_by: session!.user.id, is_shared: true, business_unit: businessUnit }),
    });
    if (res.ok) { showToast(`"${newListName}" saved`); setNewListName(''); setShowSaveList(false); loadSmartLists(); }
    else showToast('Error saving list');
  }

